-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql.
--
-- Personajes de Honkai: Star Rail: 92. Cada fila lleva todo: datos, icono, biografia y
-- materiales de ascension.
--
-- Los datos son una copia de la base de datos tal y como estaba el 2026-09-15.
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada: los
-- favoritos, tier lists y guias de los usuarios que apuntan a estas filas se
-- conservan. Ojo: si has cambiado algo desde la app despues de esa fecha,
-- ejecutarlo lo devuelve a como estaba en la copia.

insert into public.characters (
  id, game_id, name, image_url, rarity, element, level_cap, description, role, path, signature, is_upcoming, biography, biography_source, biography_en, biography_source_en, biography_es, biography_source_es, biography_es_translated, ascension
)
values
  ('hsr-acheron', 'honkai-star-rail', 'Acheron', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1308.png', '5', 'Rayo', 80, null, 'DPS', 'Nihilidad', 'En la orilla inalcanzable', false, 'A drifter claiming to be a Galaxy Ranger. Her true name is unknown. She walks the cosmos alone, carrying with her a long sword.

A drifter claiming to be a Galaxy Ranger. Her true name is unknown, and she walks the cosmos alone, carrying with her a long sword. Though aloof and taciturn, her blade flicks out like lashing lightning. And yet, she always strikes with her scabbard, never drawing the sword free.', 'https://honkai-star-rail.fandom.com/wiki/Acheron%2FLore', 'A drifter claiming to be a Galaxy Ranger. Her true name is unknown. She walks the cosmos alone, carrying with her a long sword.

A drifter claiming to be a Galaxy Ranger. Her true name is unknown, and she walks the cosmos alone, carrying with her a long sword. Though aloof and taciturn, her blade flicks out like lashing lightning. And yet, she always strikes with her scabbard, never drawing the sword free.', 'https://honkai-star-rail.fandom.com/wiki/Acheron%2FLore', '"... Los guerreros no eligen sus espadas, sus espadas los eligen a ellos. ██████████████████████████████████████████████████████████████████████████... Ese día, cuando vi que le dieron la espada que hice a esa chica, me di cuenta de que en la pelea contra ▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇, ella eligió, o fue elegida, para aceptar el camino que ▇▇▇▇▇▇▇▇▇ la llevó hacia un nuevo mañana. ▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇ habrá un futuro brillante. A pesar del peligro que acecha al Reino Izumo, su gente mantiene la esperanza y cree que un día los ▇▇▇▇▇▇▇▇▇ serán derrotados y el mundo quedará liberado... ▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇▇...".

Fragmento de un antiguo manuscrito', 'https://honkai-star-rail.fandom.com/es/wiki/Acheron', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","nombre":"Componente del acumulador de sueños","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","nombre":"Componente del acumulador de sueños","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110414.png","nombre":"Báculo del Cambiaformas","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","nombre":"Válvula del flujo de sueños","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110414.png","nombre":"Báculo del Cambiaformas","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","nombre":"Válvula del flujo de sueños","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110414.png","nombre":"Báculo del Cambiaformas","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","nombre":"Motor creasueños","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110414.png","nombre":"Báculo del Cambiaformas","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","nombre":"Motor creasueños","cantidad":9}]}]'::jsonb),
  ('hsr-aglaea', 'honkai-star-rail', 'Aglaea', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1402.png', '5', 'Rayo', 80, null, 'Sub-DPS / Debuffer (Congelación)', 'Memoria', 'Cono de firma de Aglaea', false, 'In that holy city kissed by the dawn, the weaver caresses the golden threads, entwining fates. The Chrysos Heir that bears the "Romance" Coreflame gathered the world''s heroes, leading them on a long journey once more —to topple the gods, reclaim the divine flame, and grand rebirth to the nearly fallen Amphoreus.

In that holy city kissed by the dawn, the weaver caresses the golden threads, entwining fates. The Chrysos Heir that bears the "Romance" Coreflame gathered the world''s heroes, leading them on a long journey once more — to topple the gods, reclaim the divine flame, and grant rebirth to the nearly fallen Amphoreus.', 'https://honkai-star-rail.fandom.com/wiki/Aglaea%2FLore', 'In that holy city kissed by the dawn, the weaver caresses the golden threads, entwining fates. The Chrysos Heir that bears the "Romance" Coreflame gathered the world''s heroes, leading them on a long journey once more —to topple the gods, reclaim the divine flame, and grand rebirth to the nearly fallen Amphoreus.

In that holy city kissed by the dawn, the weaver caresses the golden threads, entwining fates. The Chrysos Heir that bears the "Romance" Coreflame gathered the world''s heroes, leading them on a long journey once more — to topple the gods, reclaim the divine flame, and grant rebirth to the nearly fallen Amphoreus.', 'https://honkai-star-rail.fandom.com/wiki/Aglaea%2FLore', 'Años después, cuando de manera inesperada encuentra una prenda que tejió en su juventud, la ternura emana de la seda, sacudiendo suavemente su corazón que llevaba tanto tiempo en silencio.

En la familia consagrada a Mnestia, a cada miembro, desde su juventud, se le enseñaba el arte de la belleza. Los retratos de los grandes maestros cuelgan en la pared de honor del baño privado, vigilando siempre a su descendencia. Mientras muchos se quedan sin habla bajo el escrutinio de esos maestros, ella se mueve con una gracia tan natural que parece no esforzarse bajo su mirada. "La pintura sucumbe a la falsedad, la música a la abstracción, la escultura a la pesadez, y el drama a lo mundano...". Los ancianos mostraban signos claros de derrota, pero su voz, joven y resuelta, acallaba cualquier objeción. "Pequeña Aglaea, ¿hay algo más bello que esto?". Saliendo del baño, danza de puntillas hasta el espejo. Su cabello dorado y pálido caía como una cascada. "No".', 'https://honkai-star-rail.fandom.com/es/wiki/Aglaea', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","nombre":"Carne pisoteada del miedo","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","nombre":"Carne pisoteada del miedo","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110424.png","nombre":"Clavo del ataúd bestial","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","nombre":"Pecho hendido del valor","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110424.png","nombre":"Clavo del ataúd bestial","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","nombre":"Pecho hendido del valor","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110424.png","nombre":"Clavo del ataúd bestial","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","nombre":"Torso bautizado de gloria","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110424.png","nombre":"Clavo del ataúd bestial","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","nombre":"Torso bautizado de gloria","cantidad":9}]}]'::jsonb),
  ('hsr-anaxa', 'honkai-star-rail', 'Anaxa', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1405.png', '5', 'Viento', 80, null, 'DPS', 'Erudición', 'Cono de firma de Anaxa', false, 'The Grove of Epiphany, where knowledge flourishes and philosophers are born. Yet here stands Anaxagoras the blasphemer, the Chrysos Heir who challenges the Coreflame of Reason. He is questioned: Would you defy the prophecy even if you must bear infamy, and insist on driving the thorns of doubt into the Sacred Tree of wisdom? ——"Ridiculous. In a world full of lies, I am the only truth."', 'https://honkai-star-rail.fandom.com/wiki/Anaxa%2FLore', 'The Grove of Epiphany, where knowledge flourishes and philosophers are born. Yet here stands Anaxagoras the blasphemer, the Chrysos Heir who challenges the Coreflame of Reason. He is questioned: Would you defy the prophecy even if you must bear infamy, and insist on driving the thorns of doubt into the Sacred Tree of wisdom? ——"Ridiculous. In a world full of lies, I am the only truth."', 'https://honkai-star-rail.fandom.com/wiki/Anaxa%2FLore', '"Ah, naciste en una polis lejana. Tus padres fallecieron muy pronto. Te quedaste solo con tu hermana mayor y vivían del poco dinero que ganaba domesticando animales. Eras solitario desde pequeño. Cuando los niños de tu edad estaban jugando en los campos, tú te escondías detrás de un árbol y recogías las hojas que habían caído.

"¿Por qué los dromas no pueden volar?", murmuras mientras observas al droma que creció a tu lado. "¡Es porque en su vida anterior era un ratón de biblioteca como tú!". Has oído esta frase muchas veces, pero nunca entendiste por qué se usaba como burla.

"Si los dioses son omnipotentes, ¿por qué temen a la muerte?". En el templo donde se leen las enseñanzas sagradas, las cosas que deberían ser incuestionables te hacen dudar. "¡Lárgate, Anaxágoras!". Los sacerdotes enfurecidos a menudo te echaban del templo.

Tu hermana nunca te culpaba. En lugar de eso, empleaba una parte de sus escasos ingresos para comprarte los libros y las herramientas que tanto anhelabas.', 'https://honkai-star-rail.fandom.com/es/wiki/Anaxa', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","nombre":"Augurio etéreo","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","nombre":"Augurio etéreo","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110425.png","nombre":"Copa de la era embriagada","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","nombre":"Gemido resonante","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110425.png","nombre":"Copa de la era embriagada","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","nombre":"Gemido resonante","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110425.png","nombre":"Copa de la era embriagada","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","nombre":"Lamento eterno","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110425.png","nombre":"Copa de la era embriagada","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","nombre":"Lamento eterno","cantidad":9}]}]'::jsonb),
  ('hsr-archer', 'honkai-star-rail', 'Archer (Collab)', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1015.png', '5', 'Cuántico', 80, null, 'DPS', 'Cacería', 'Cono de evento/firma', false, 'Despair plays in cycles between the past and future. Countless ideals were incinerated before that red garment. Yet, do not let this smear of ashes fool you — Should someone create a phantasmal sweet dream under the guise of false ideals, then he will burn again, facing down the hypocrites of the world till the very end. No matter where he is, he always remains the steadfast champion of justice.', 'https://honkai-star-rail.fandom.com/wiki/Archer%2FLore', 'Despair plays in cycles between the past and future. Countless ideals were incinerated before that red garment. Yet, do not let this smear of ashes fool you — Should someone create a phantasmal sweet dream under the guise of false ideals, then he will burn again, facing down the hypocrites of the world till the very end. No matter where he is, he always remains the steadfast champion of justice.', 'https://honkai-star-rail.fandom.com/wiki/Archer%2FLore', 'Como regla general, es un hombre racional, capaz de mantener la calma y completar su trabajo. Pero, igual que ciertos empleados veteranos, a veces no puede evitar mostrar una visión pesimista de la vida, que se manifiesta en forma de desprecio hacia sí mismo. Por eso, a menudo dice cosas que pueden parecer duras.

"No, eso no es del todo cierto". "La mayoría de la gente no puede deshacerse del desprecio que sienten por sí mismas a medida que maduran, porque no pueden luchar contra su yo del pasado". "Pero luchar no siempre es la solución". "... Mejor olvidemos este tema".

En resumen, siempre que evite cruzarse con su versión más inmadura del pasado o con alguien que se le parezca demasiado, este hombre demuestra ser un Servant excepcionalmente estable y maduro. Aunque a menudo se queja de las responsabilidades que tiene ahora, lleva a cabo cada tarea con absoluta entrega y atención meticulosa.', 'https://honkai-star-rail.fandom.com/es/wiki/Archer', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":9}]}]'::jsonb),
  ('hsr-argenti', 'honkai-star-rail', 'Argenti', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1302.png', '5', 'Físico', 80, null, 'DPS', 'Erudición', 'Un instante frente a la mirada', false, 'A paragon knight of the Knights of Beauty who is piously seeking his missing Aeon, Idrila the Beauty. Forthright and candid, he wanders the cosmos espousing the virtues of Idrila''s good name.

A paragon knight of the Knights of Beauty. He embodies righteousness and honor, possessing an admirable nobility. As a solitary wanderer in the cosmos, he wholeheartedly embraces the principles of "Beauty." Upholding the honor of beauty in the universe has been Argenti''s sacred duty. From the very beginning, he approached this duty with piety and unwavering conviction.', 'https://honkai-star-rail.fandom.com/wiki/Argenti%2FLore', 'A paragon knight of the Knights of Beauty who is piously seeking his missing Aeon, Idrila the Beauty. Forthright and candid, he wanders the cosmos espousing the virtues of Idrila''s good name.

A paragon knight of the Knights of Beauty. He embodies righteousness and honor, possessing an admirable nobility. As a solitary wanderer in the cosmos, he wholeheartedly embraces the principles of "Beauty." Upholding the honor of beauty in the universe has been Argenti''s sacred duty. From the very beginning, he approached this duty with piety and unwavering conviction.', 'https://honkai-star-rail.fandom.com/wiki/Argenti%2FLore', 'La guerra arrasó con su hogar por años, y los horrores del derramamiento de sangre y los incesantes bombardeos contaminaron sus recuerdos de la infancia. En medio del caos, buscó refugio bajo tierra y por suerte encontró una ocarina debajo de una baldosa de piedra. Con sus manos temblorosas, trató de tocar una melodía con el instrumento. Sin embargo, su "música" era horrible.

Sí, las notas etéreas que emanaban de su ocarina se convirtieron en su santuario, un escape espiritual de la cruda realidad.

Con el tiempo, los acordes melódicos se desvanecieron en los huecos de su memoria y se convirtieron en un momento misterioso y escurridizo. Años después, durante una gira de los bardos, cuando salvó a un niño de las llamas de la guerra y recibió una preciosa ocarina en forma de agradecimiento, las melodías de su pasado regresaron. Al sostener el bellísimo instrumento en sus manos, examinó su impecable y noble fabricación.', 'https://honkai-star-rail.fandom.com/es/wiki/Argenti', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110411.png","nombre":"Pase del inframundo","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110411.png","nombre":"Pase del inframundo","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110411.png","nombre":"Pase del inframundo","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110411.png","nombre":"Pase del inframundo","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":9}]}]'::jsonb),
  ('hsr-arlan', 'honkai-star-rail', 'Arlan', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1008.png', '4', 'Rayo', 80, null, 'DPS', 'Destrucción', 'Voto secreto', false, 'The head of Herta Space Station''s Security Department. This quiet boy hopes to protect the researchers who value their pursuit of knowledge, and to help them to complete their work.

The inarticulate head of the Security Department. While scientific research is beyond his understanding, Arlan is willing to risk his life to protect the staff who value research so very much. He is used to pain and wears his scars like badges of honor. Only when holding Peppy does the boy let down his guard and show a rare smile.', 'https://honkai-star-rail.fandom.com/wiki/Arlan%2FLore', 'The head of Herta Space Station''s Security Department. This quiet boy hopes to protect the researchers who value their pursuit of knowledge, and to help them to complete their work.

The inarticulate head of the Security Department. While scientific research is beyond his understanding, Arlan is willing to risk his life to protect the staff who value research so very much. He is used to pain and wears his scars like badges of honor. Only when holding Peppy does the boy let down his guard and show a rare smile.', 'https://honkai-star-rail.fandom.com/wiki/Arlan%2FLore', '¿Cómo se puede evaluar el trabajo de seguridad de Arlan? -Es el faro que guía al Departamento de Seguridad; ¡el núcleo en el que se apoyan todos! Sin él, la Estación Espacial se desmoronaría en un día; sin él, la vida de la gente se arruinaría en diez días; ¡sin él, la estación sería un infierno en solo cien días! -Pero juega al holodisco volador con Peppy en horas de trabajo. -Porque termina todas las tareas diarias de seguridad antes de lo previsto. Su mera presencia es una inspiración para todos nosotros. -Pero juega al holodisco volador con Peppy durante las horas de trabajo. -¿Cómo sabes que jugar al holodisco con Peppy no forma parte de su trabajo?

"No está permitido mirar el teléfono mientras estás de patrulla. Dámelo". "Arlan, la gente está hablando mal de ti en el chat. ¿No te importa?". "No, estoy demasiado ocupado". "¿Eh? ¿Tienes una misión urgente? Déjame ir contigo. ¿Qué pasó?". "Voy a llevar a Peppy al veterinario y luego jugaremos al holodisco volador".', 'https://honkai-star-rail.fandom.com/es/wiki/Arlan', false, '[{"desde":20,"hasta":30,"creditos":3200,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":4}]},{"desde":30,"hasta":40,"creditos":6400,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":8}]},{"desde":40,"hasta":50,"creditos":12800,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110404.png","nombre":"Corona de rayos de la sombra del pasado","cantidad":2},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":5}]},{"desde":50,"hasta":60,"creditos":32000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110404.png","nombre":"Corona de rayos de la sombra del pasado","cantidad":5},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":8}]},{"desde":60,"hasta":70,"creditos":64000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110404.png","nombre":"Corona de rayos de la sombra del pasado","cantidad":15},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":5}]},{"desde":70,"hasta":80,"creditos":128000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110404.png","nombre":"Corona de rayos de la sombra del pasado","cantidad":28},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":7}]}]'::jsonb),
  ('hsr-ashveil', 'honkai-star-rail', 'Ashveil', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1504.png', '5', 'Rayo', null, null, null, 'Cacería', null, false, null, null, null, null, null, null, false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","nombre":"Crayón de la inocencia","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","nombre":"Crayón de la inocencia","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110434.png","nombre":"Rasgueo tormentoso","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","nombre":"Pluma creasueños","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110434.png","nombre":"Rasgueo tormentoso","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","nombre":"Pluma creasueños","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110434.png","nombre":"Rasgueo tormentoso","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","nombre":"Pincel de los sueños","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110434.png","nombre":"Rasgueo tormentoso","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","nombre":"Pincel de los sueños","cantidad":9}]}]'::jsonb),
  ('hsr-asta', 'honkai-star-rail', 'Asta', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1009.png', '4', 'Fuego', 80, null, 'Buffer', 'Armonía', 'Encuentro planetario / ¡A bailar!', false, 'The lead researcher of Herta Space Station and a lady from a renowned family. She''s an astronomer overflowing with curiosity, and excels at managing the disparate staff of the space station.

A fiercely inquisitive and energetic young girl. She is the Lead Researcher of the . Whether it is managing opinionated staff, or courteously but firmly responding to the Intelligentsia Guild''s devious demands, Asta handles it all effortlessly. After all... commanding a space station is much easier than taking over the family business!', 'https://honkai-star-rail.fandom.com/wiki/Asta%2FLore', 'The lead researcher of Herta Space Station and a lady from a renowned family. She''s an astronomer overflowing with curiosity, and excels at managing the disparate staff of the space station.

A fiercely inquisitive and energetic young girl. She is the Lead Researcher of the . Whether it is managing opinionated staff, or courteously but firmly responding to the Intelligentsia Guild''s devious demands, Asta handles it all effortlessly. After all... commanding a space station is much easier than taking over the family business!', 'https://honkai-star-rail.fandom.com/wiki/Asta%2FLore', 'Cuando aún era pequeña y empezaba a elegir su propio telescopio, Asta oía a menudo los débiles murmullos de los ancianos alabándola. Estaba bastante orgullosa de eso, porque era capaz de distinguir el artesano y el sistema de guía astral de cada telescopio con un simple vistazo. No fue hasta un día que se puso más cerca cuando se enteró de que en realidad se burlaban de ella: ¿cómo podía una niña tan pequeña querer un objeto tan extremadamente caro? Las aficiones personales no existían a los ojos de esa gente. Lo único que veían era una princesita mimada. "¿Te gustan las estrellas? Oh, lo entiendo, cariño. Te gustan las cosas brillantes, ¿no?". "Eh... Bueno, sí. Ahora mismo estoy investigando protoestrellas, y espero descubrir algún día un nuevo sistema estelar. Le pondré mi nombre... Como aquellos famosos astrónomos de antaño". "¿Eso es todo? Podemos ponerle tu nombre a un planeta por tu cumpleaños. ¿O qué tal dos? En realidad, es bastante barato". "..." "Oye, ¿a dónde vas? ¡Asta!".', 'https://honkai-star-rail.fandom.com/es/wiki/Asta', false, '[{"desde":20,"hasta":30,"creditos":3200,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","nombre":"Pin del guardia","cantidad":4}]},{"desde":30,"hasta":40,"creditos":6400,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","nombre":"Pin del guardia","cantidad":8}]},{"desde":40,"hasta":50,"creditos":12800,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110402.png","nombre":"Quitina endoterma","cantidad":2},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","nombre":"Insignia del guardia","cantidad":5}]},{"desde":50,"hasta":60,"creditos":32000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110402.png","nombre":"Quitina endoterma","cantidad":5},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","nombre":"Insignia del guardia","cantidad":8}]},{"desde":60,"hasta":70,"creditos":64000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110402.png","nombre":"Quitina endoterma","cantidad":15},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","nombre":"Medalla del guardia","cantidad":5}]},{"desde":70,"hasta":80,"creditos":128000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110402.png","nombre":"Quitina endoterma","cantidad":28},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","nombre":"Medalla del guardia","cantidad":7}]}]'::jsonb),
  ('hsr-aventurine', 'honkai-star-rail', 'Aventurino (Aventurine)', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1304.png', '5', 'Imaginario', 80, null, 'Tanque / Sub-DPS', 'Conservación', 'El destino nunca es justo', false, 'A high-ranking executive of the IPC''s Strategic Investment Department. A risk-taker, his constant smile makes it difficult for people to discern his true feelings.

Senior manager of the Strategic Investment Department at the IPC and one of the Ten Stonehearts. His Cornerstone is the "aventurine of stratagems." An ostentatious risk-taker, he often wears a smile that masks his true motives. He won his current position by wagering against fate itself. He views life as a high-stakes, high-return investment, and he plays this particular gamble with masterful ease.', 'https://honkai-star-rail.fandom.com/wiki/Aventurine%2FLore', 'A high-ranking executive of the IPC''s Strategic Investment Department. A risk-taker, his constant smile makes it difficult for people to discern his true feelings.

Senior manager of the Strategic Investment Department at the IPC and one of the Ten Stonehearts. His Cornerstone is the "aventurine of stratagems." An ostentatious risk-taker, he often wears a smile that masks his true motives. He won his current position by wagering against fate itself. He views life as a high-stakes, high-return investment, and he plays this particular gamble with masterful ease.', 'https://honkai-star-rail.fandom.com/wiki/Aventurine%2FLore', '"Tengo algo de que informarte sobre el nuevo empleado".

"¿Por qué estás tan preocupado, Erwin?".

"Son quejas sobre él, tanto formales como informales. Están inundando mi buzón como trozos de papel infinitos. Me pregunto... si vale la pena reconsiderar su inclusión en el Departamento de Inversiones Estratégicas".

"¿Qué dicen esas quejas?".

"Principalmente sobre sus orígenes. Esos ojos suyos...". "Una vez engañaron al Departamento de Desarrollo de Mercados afirmando falsamente que había fuentes de energía ocultas en la tierra estéril de Sigonia, aún no desarrolladas ni utilizadas eficazmente. Invertimos una enorme cantidad de fondos en su excavación para darnos cuenta de que todo era una estafa". "Y luego está el tristemente célebre «Caso de Aventurino Egyhazo». Engañó a la Sociedad del Conocimiento haciéndole creer que los restos de Tayzzyronth el Imperator Insectorum estaban enterrados allí.', 'https://honkai-star-rail.fandom.com/es/wiki/Aventurino', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","nombre":"Jirones de pensamientos","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","nombre":"Jirones de pensamientos","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110417.png","nombre":"Edicto de la contención","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","nombre":"Fragmento de impresiones","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110417.png","nombre":"Edicto de la contención","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","nombre":"Fragmento de impresiones","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110417.png","nombre":"Edicto de la contención","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","nombre":"Fragmento de deseos","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110417.png","nombre":"Edicto de la contención","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","nombre":"Fragmento de deseos","cantidad":9}]}]'::jsonb),
  ('hsr-aventurine-waveflair', 'honkai-star-rail', 'Aventurino Oleaje (Aventurine • Waveflair)', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1513.png', '5', 'Cuántico', null, null, null, 'Júbilo', null, true, null, null, null, null, null, null, false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","nombre":"Jirones de pensamientos","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","nombre":"Jirones de pensamientos","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110443.png","nombre":"Máscara grotesca de la risita burlona","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","nombre":"Fragmento de impresiones","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110443.png","nombre":"Máscara grotesca de la risita burlona","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","nombre":"Fragmento de impresiones","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110443.png","nombre":"Máscara grotesca de la risita burlona","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","nombre":"Fragmento de deseos","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110443.png","nombre":"Máscara grotesca de la risita burlona","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","nombre":"Fragmento de deseos","cantidad":9}]}]'::jsonb),
  ('hsr-bailu', 'honkai-star-rail', 'Bailu', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1211.png', '5', 'Rayo', 80, null, 'Support (Healer)', 'Abundancia', 'El tiempo no espera a nadie', false, 'The High Elder of the Vidyadhara, who is also known as the "Healer Lady" on the Luofu. She uses her unique medical science and the medical treatment that can only be provided by the Vidyadhara dragon race to save lives.

A vivacious young lady of the Vidyadhara race, she is known as the "Healer Lady" due to her expertise with medicine. She often dishes out unorthodox prescriptions such as "Stay well hydrated" and "Get a good night''s rest." Bailu cannot bear to see people suffer, and that''s why you''ll see her with her eyes shut tightly as she cures ailments. "As long as they''re cured, that''s all that matters, right?"', 'https://honkai-star-rail.fandom.com/wiki/Bailu%2FLore', 'The High Elder of the Vidyadhara, who is also known as the "Healer Lady" on the Luofu. She uses her unique medical science and the medical treatment that can only be provided by the Vidyadhara dragon race to save lives.

A vivacious young lady of the Vidyadhara race, she is known as the "Healer Lady" due to her expertise with medicine. She often dishes out unorthodox prescriptions such as "Stay well hydrated" and "Get a good night''s rest." Bailu cannot bear to see people suffer, and that''s why you''ll see her with her eyes shut tightly as she cures ailments. "As long as they''re cured, that''s all that matters, right?"', 'https://honkai-star-rail.fandom.com/wiki/Bailu%2FLore', '"Recopilación de casos y tratamientos de la Comisión de Alquimia, volumen 48, caso de estudio 1246

Doctora encargada: Bailu.

Paciente: Yuezhui, mujer raposiana de sesenta y dos años.

Afección: Por accidente, comió un dulce de chocolate que le vendió un comerciante foráneo. Experimentó una sed extrema por la que tomó agua en exceso; mucho dolor, en particular en el estómago; dificultad para respirar y pérdida de mechones de la cola.

Diagnóstico: Intoxicación alimentaria.

Receta: 1 mas de ginseng amargo, 1 mas y 1 condrín de regaliz crudo, 1 botella de elixir de jade de cinco granos y una copia del folleto «Lo que debe saber de los alimentos prohibidos».

Instrucciones: Hervir el ginseng amargo y el regaliz crudo en el elixir de jade de cinco granos hasta que se reduzca a la mitad, colar para eliminar los restos, beber hasta que vomite.', 'https://honkai-star-rail.fandom.com/es/wiki/Bailu', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110404.png","nombre":"Corona de rayos de la sombra del pasado","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110404.png","nombre":"Corona de rayos de la sombra del pasado","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110404.png","nombre":"Corona de rayos de la sombra del pasado","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110404.png","nombre":"Corona de rayos de la sombra del pasado","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":9}]}]'::jsonb),
  ('hsr-black-swan', 'honkai-star-rail', 'Black Swan', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1307.png', '5', 'Viento', 80, null, 'Sub-DPS / Debuffer (DoT)', 'Nihilidad', 'Recuerdo reconstruido', false, 'A Memokeeper of the Garden of Recollection. An indolent and mysterious soothsayer. "Remembrance" of men are hers to heed, threads of fate are hers to tug.

A Memokeeper of the Garden of Recollection. A mysterious and elegant soothsayer. She often wears a warm smile and is willing to patiently listen to the words of others, thus using such means as a pretext to enter "memories" and gain omniscience over certain matters. A lady passionate about collecting unique memories, yet the thoughts that guide her are hard to glean.', 'https://honkai-star-rail.fandom.com/wiki/Black%20Swan%2FLore', 'A Memokeeper of the Garden of Recollection. An indolent and mysterious soothsayer. "Remembrance" of men are hers to heed, threads of fate are hers to tug.

A Memokeeper of the Garden of Recollection. A mysterious and elegant soothsayer. She often wears a warm smile and is willing to patiently listen to the words of others, thus using such means as a pretext to enter "memories" and gain omniscience over certain matters. A lady passionate about collecting unique memories, yet the thoughts that guide her are hard to glean.', 'https://honkai-star-rail.fandom.com/wiki/Black%20Swan%2FLore', '"Es una niña inusual, y lo supe desde el día en que nació. Parecía como si la naturaleza celebrara su llegada: los pájaros cantaban y la luna y el sol se unieron en el cielo. Las cartas en mi mano parecían insinuar el surgimiento de un alma impregnada de nostalgia. Desde temprana edad, le fascinaban las historias del pasado. Se quedaba absorta pensando en nuestros orígenes, nuestros creadores e incluso el mismísimo inicio del mundo. Sus preguntas harían que hasta los eruditos más estudiosos se rascaran la cabeza. Sí, algunos niños la molestaban por hacer preguntas tan profundas, pero ¿acaso no son preguntas importantes? La vida es similar a un laberinto serpenteante donde los recuerdos son lo único que nos acompaña". — Los recuerdos de una madre

Su madre tenía amnesia y olvidaba muchas cosas, lo que le dificultaba reconocer a su familia o recordar eventos recientes. Aferrada al diagnóstico de la amnesia, abrazó con fuerza a su madre tratando de leerle en voz alta su último diario.', 'https://honkai-star-rail.fandom.com/es/wiki/Cisne%20Negro', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110415.png","nombre":"Vestigios elevados","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110415.png","nombre":"Vestigios elevados","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110415.png","nombre":"Vestigios elevados","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110415.png","nombre":"Vestigios elevados","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":9}]}]'::jsonb),
  ('hsr-blade', 'honkai-star-rail', 'Blade', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1205.png', '5', 'Viento', 80, null, 'DPS', 'Destrucción', 'El lado inalcanzable', false, 'A member of the Stellaron Hunters, and a swordsman who abandoned his body to become a blade. Pledges loyalty to "Destiny''s Slave," and possesses a terrifying self-healing ability.

A swordsman who abandoned his body to become a blade. Birth name unknown. He pledges loyalty to "Destiny''s Slave," and possesses a terrifying self-healing ability. Blade wields an ancient sword riddled with cracks, just like his body and his mind.', 'https://honkai-star-rail.fandom.com/wiki/Blade%2FLore', 'A member of the Stellaron Hunters, and a swordsman who abandoned his body to become a blade. Pledges loyalty to "Destiny''s Slave," and possesses a terrifying self-healing ability.

A swordsman who abandoned his body to become a blade. Birth name unknown. He pledges loyalty to "Destiny''s Slave," and possesses a terrifying self-healing ability. Blade wields an ancient sword riddled with cracks, just like his body and his mind.', 'https://honkai-star-rail.fandom.com/wiki/Blade%2FLore', 'Lo único que percibió fue una mancha carmesí en los ojos y un sabor metálico en la boca. Sus extremidades no respondían.
Debía estar muerto.

"¿Ya lo has aprendido?".
Abrió la boca, perdido, con la voz tan ronca como la de una bestia salvaje.
Su garganta dejó de emitir sonidos abruptamente, tan pronto como el objeto frío y duro perforó su torso.
Una y otra y otra vez, el proceso se repitió mil veces.

Maravilloso. Mientras sus fibras musculares se desgarraban, oía el sutil sonido que producían los tendones al unirse y conectarse de nuevo.
Qué maravilla. El monstruo dentro de su cuerpo se alimentaba, pero quería más, quería convertirse en una bestia enorme.
¡Qué maravilla! Ya había perdido toda voluntad de sobrevivir, pero aun así su cuerpo se regeneraba solo.
Simplemente maravilloso.

Antes de que la espada perforara una vez más su piel, la agarró con las manos desnudas y se incorporó lentamente.
"¿Ya lo has aprendido?".
Se encontró con los ojos de la mujer, rojos como la sangre.', 'https://honkai-star-rail.fandom.com/es/wiki/Blade', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110415.png","nombre":"Vestigios elevados","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110415.png","nombre":"Vestigios elevados","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110415.png","nombre":"Vestigios elevados","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110415.png","nombre":"Vestigios elevados","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":9}]}]'::jsonb),
  ('hsr-boothill', 'honkai-star-rail', 'Boothill', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1315.png', '5', 'Físico', 80, null, 'DPS', 'Cacería', 'Navegando hacia una segunda vida', false, 'A cyborg cowboy drifting among the stars. Extremely optimistic and unrestrained. He is a member of the Galaxy Rangers who swore to punish the wretched by any and all means... His flamboyant and brash actions were all to draw the attention of the Interastral Peace Corporation — the target of his revenge.', 'https://honkai-star-rail.fandom.com/wiki/Boothill%2FLore', 'A cyborg cowboy drifting among the stars. Extremely optimistic and unrestrained. He is a member of the Galaxy Rangers who swore to punish the wretched by any and all means... His flamboyant and brash actions were all to draw the attention of the Interastral Peace Corporation — the target of his revenge.', 'https://honkai-star-rail.fandom.com/wiki/Boothill%2FLore', '"¡Graey, hay un niño ahí en la nieve!". Graey y Nick se acercaron con cautela y levantaron al niño, que tenía la cara toda roja y lloraba sin cesar. El niño tenía un nombre llamativo y bonito que en la antigua lengua de Aeragan-Epharshel significaba "arma cargada".

Creció con el amor y la protección de Graey y Nick, mientras jugaba alegremente con sus hermanos. Aunque todos venían de lugares diferentes, ahora pertenecían a este vasto continente llamado "Aeragan-Epharshel". Graey lo llevó a conocer las plantas, los animales y los ríos. Nick le enseñó a domar caballos y a criar ovejas. Ya de muy joven, montaba su potro sobre los arroyos y seguía a Nick cuando trasladaban su ganado a los campos ricos en agua y verdor bajo el sol pleno de la mañana. Nick siempre cantaba a viva voz cuando la luz brillaba sobre las grandes nubes. Cuando lo escuchaba cantar, abría la boca y se ponía a cantar también, con voz clara y nítida.', 'https://honkai-star-rail.fandom.com/es/wiki/Boothill', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","nombre":"Jirones de pensamientos","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","nombre":"Jirones de pensamientos","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110421.png","nombre":"Permiso de trabajo de la Corporación","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","nombre":"Fragmento de impresiones","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110421.png","nombre":"Permiso de trabajo de la Corporación","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","nombre":"Fragmento de impresiones","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110421.png","nombre":"Permiso de trabajo de la Corporación","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","nombre":"Fragmento de deseos","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110421.png","nombre":"Permiso de trabajo de la Corporación","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","nombre":"Fragmento de deseos","cantidad":9}]}]'::jsonb),
  ('hsr-bronya', 'honkai-star-rail', 'Bronya', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1101.png', '5', 'Viento', 80, null, 'Buffer', 'Armonía', 'La batalla no ha terminado', false, 'Heir apparent to the Supreme Guardian of Belobog. She possesses pride befitting of a princess, but also the determination and integrity of a soldier.

Heir to the Supreme Guardian of Belobog, she is the young and capable commander of the Silvermane Guards. Bronya received a rigorous education from an early age, and as such, possesses the grace and affinity as expected of an heir. However, after witnessing the abysmal conditions in the Underworld, seeds of doubt begin growing in the mind of Belobog''s future leader. "Can all the training I''ve received really help me lead the people to the lives they want?"', 'https://honkai-star-rail.fandom.com/wiki/Bronya%2FLore', 'Heir apparent to the Supreme Guardian of Belobog. She possesses pride befitting of a princess, but also the determination and integrity of a soldier.

Heir to the Supreme Guardian of Belobog, she is the young and capable commander of the Silvermane Guards. Bronya received a rigorous education from an early age, and as such, possesses the grace and affinity as expected of an heir. However, after witnessing the abysmal conditions in the Underworld, seeds of doubt begin growing in the mind of Belobog''s future leader. "Can all the training I''ve received really help me lead the people to the lives they want?"', 'https://honkai-star-rail.fandom.com/wiki/Bronya%2FLore', 'Aprendió a ocultar sus pensamientos desde una edad temprana. Todos los días recorría los mismos caminos con los demás niños, jugaba a los mismos juegos y chismeaba de las mismas cosas. Pero nunca se sintió abrumada por la naturaleza trivial y anodina de la vida: cada vez que estaba sola, se sentaba en su banco de piedra blancuzca, mirando al cielo e imaginándoselo perfecto y completo, sin la obstrucción de ese disco plano. Veía a los jornaleros chorreando sudor, sus ansias de vivir aplastadas por la presión de la supervivencia. Al ver la mirada cansada, pero sincera de sus ojos, se sumió en la confusión. ¿La vida de veras tiene que ser así? Igual que la inmensidad del cielo fue diseccionada por aquel monstruoso disco de acero, quizás la libertad que ella anhelaba también estaba destinada a ser incompleta. Luchó por salir de ese atolladero, grabando en silencio en aquel camino de piedra polvoriento los ideales que llegaría a implantar en su vida. "Hacer del mundo un lugar mejor".', 'https://honkai-star-rail.fandom.com/es/wiki/Bronya', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","nombre":"Pin del guardia","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","nombre":"Pin del guardia","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110405.png","nombre":"Ojo del vendaval","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","nombre":"Insignia del guardia","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110405.png","nombre":"Ojo del vendaval","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","nombre":"Insignia del guardia","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110405.png","nombre":"Ojo del vendaval","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","nombre":"Medalla del guardia","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110405.png","nombre":"Ojo del vendaval","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","nombre":"Medalla del guardia","cantidad":9}]}]'::jsonb),
  ('hsr-castorice', 'honkai-star-rail', 'Castorice', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1407.png', '5', 'Cuántico', 80, null, 'Support / Debuffer', 'Memoria', 'Cono de firma de Castorice', false, 'Aidonia, the snowy land that respects and worships death, has already sunken into sweet slumber. O Castorice, daughter of the River of Souls, the Chrysos Heir in search of the Coreflame of "Death," set forth! Guard the lament of the souls in this world, and embrace the solitude of destiny. — Life and death is a journey. When a butterfly rests on that dead branch, the withered will be reborn again.', 'https://honkai-star-rail.fandom.com/wiki/Castorice%2FLore', 'Aidonia, the snowy land that respects and worships death, has already sunken into sweet slumber. O Castorice, daughter of the River of Souls, the Chrysos Heir in search of the Coreflame of "Death," set forth! Guard the lament of the souls in this world, and embrace the solitude of destiny. — Life and death is a journey. When a butterfly rests on that dead branch, the withered will be reborn again.', 'https://honkai-star-rail.fandom.com/wiki/Castorice%2FLore', 'Desde que tiene uso de razón, la nieve en Aidonia siempre ha estado ahí. Es como si el tiempo se hubiera congelado en esta tierra blanca y silenciosa. De pequeña, le preguntó a Amunet qué era la nieve. Amunet respondió que era la alegría y la tristeza de la vida mortal.

Siempre permanecía ensimismada, con la mirada fija en la gente de la polis. Cada día, el guerrero bajito iba a entrenar ante las puertas del templo, el sacerdote de mediana edad cabeceaba ocasionalmente bajo la alta torre, y el erudito asceta repartía galletas de sereniflor a los niños. En la lejanía, los críos se empujaban y reían en una batalla de bolas de nieve. Sus risas caían sobre su corazón como frutos maduros. Desde la torre, intentaba distinguir sus rostros, pero siempre fracasaba.

La Doncella Sagrada. Así es como la llamaban cuando aparecía ante la gente, y nadie se atrevía a mirarla a los ojos. Cuando ella se acercaba con valentía, todos retrocedían un paso y bajaban la mirada.', 'https://honkai-star-rail.fandom.com/es/wiki/Castorice', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","nombre":"Augurio etéreo","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","nombre":"Augurio etéreo","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","nombre":"Gemido resonante","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","nombre":"Gemido resonante","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","nombre":"Lamento eterno","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","nombre":"Lamento eterno","cantidad":9}]}]'::jsonb),
  ('hsr-cerydra', 'honkai-star-rail', 'Cerydra', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1412.png', '4', 'Viento', 80, null, 'Buffer', 'Armonía', 'Cono de firma de Cerydra', false, 'The Northern Empire, a lost dynasty, where its frozen lands burn with the fever of conquest. Sovereign Cerydra, the Chrysos Heir who wields the Coreflame of "Law," weaves her schemes, contends with the gods, passes judgment upon the faithless, and lays the foundation of Flame-Chase into this world. ..."This is far from the end. Amphoreus''s journey is set to blaze across the stars!"', 'https://honkai-star-rail.fandom.com/wiki/Cerydra%2FLore', 'The Northern Empire, a lost dynasty, where its frozen lands burn with the fever of conquest. Sovereign Cerydra, the Chrysos Heir who wields the Coreflame of "Law," weaves her schemes, contends with the gods, passes judgment upon the faithless, and lays the foundation of Flame-Chase into this world. ..."This is far from the end. Amphoreus''s journey is set to blaze across the stars!"', 'https://honkai-star-rail.fandom.com/wiki/Cerydra%2FLore', 'El Imperio del Norte, Hiperión. Unas tierras gélidas que arden con ambiciones insaciables. Desde la caída del monarca sin herederos, el trono vacante ha dejado al imperio fragmentado en una interminable guerra civil.

Los refugiados que han perdido sus hogares recurren a la mendicidad para sobrevivir. Una niña herida, de inusual cabello azul, resalta con fuerza sobre la nieve inmaculada. "Solo aquellos que pertenecen a la realeza bendecida por Talanton poseen ese cabello azul que ondea como las llamas, y solo los elegidos por el cielo tienen sangre dorada corriendo por sus venas...". Con una mirada fugaz, un noble ambicioso acoge a la niña mendiga y comienza a esparcir rumores sobre una princesa perdida.

La llevan a un magnífico estrado donde el noble alza su brazo. De la punta de su dedo herido gotea una sangre tan dorada como el amanecer.', 'https://honkai-star-rail.fandom.com/es/wiki/C%C3%A9ridra', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","nombre":"Augurio etéreo","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","nombre":"Augurio etéreo","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110435.png","nombre":"Brote del crepúsculo","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","nombre":"Gemido resonante","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110435.png","nombre":"Brote del crepúsculo","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","nombre":"Gemido resonante","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110435.png","nombre":"Brote del crepúsculo","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","nombre":"Lamento eterno","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110435.png","nombre":"Brote del crepúsculo","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","nombre":"Lamento eterno","cantidad":9}]}]'::jsonb),
  ('hsr-sparxie', 'honkai-star-rail', 'Chispa (Sparxie)', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1501.png', '5', 'Fuego', null, null, null, 'Júbilo', null, false, null, null, null, null, null, null, false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","nombre":"Crayón de la inocencia","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","nombre":"Crayón de la inocencia","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110432.png","nombre":"Protuberancia radiante","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","nombre":"Pluma creasueños","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110432.png","nombre":"Protuberancia radiante","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","nombre":"Pluma creasueños","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110432.png","nombre":"Protuberancia radiante","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","nombre":"Pincel de los sueños","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110432.png","nombre":"Protuberancia radiante","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","nombre":"Pincel de los sueños","cantidad":9}]}]'::jsonb),
  ('hsr-cipher', 'honkai-star-rail', 'Cipher', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1406.png', '4', 'Cuántico', 80, null, 'Debuffer', 'Nihilidad', 'Cono de firma de Cipher', false, 'In the fallen city of bandits, Dolos, the 300 Rogues run wild and free. Race onward, fleet-footed Thief Star Cifera, Chrysos Heir of the "Trickery" Coreflame. May your web of lies spread with the breeze throughout all lands— "Tryna trick me? Not a chance!"', 'https://honkai-star-rail.fandom.com/wiki/Cipher%2FLore', 'In the fallen city of bandits, Dolos, the 300 Rogues run wild and free. Race onward, fleet-footed Thief Star Cifera, Chrysos Heir of the "Trickery" Coreflame. May your web of lies spread with the breeze throughout all lands— "Tryna trick me? Not a chance!"', 'https://honkai-star-rail.fandom.com/wiki/Cipher%2FLore', '"Al final del Mes del Tejido, el templo perdió unos panes, una bolsa de frutos secos y varias velas. Aunque estos objetos no son de gran valor, profanar lo sagrado y perturbar el orden son crímenes graves. Tras una investigación, se descubrió que la sospechosa es una chica delgada, con pelo gris y orejas de gato. Es muy ágil y astuta, por lo que se recomienda tener cuidado. Se ofrece una recompensa de 5000 por pistas y una de 10 000 a quien la atrape viva".

Cartel de "Se busca" en la ciudad de Doros

"¡Atrápenla, atrápenla!". Los latigazos y los gritos resuenan en la plaza llena de cárceles que apesta a aguas residuales. Una joven vestida con harapos sale disparada de entre la multitud, dejando un rastro de sangre dorada a su paso.

Pasa corriendo por una plataforma donde un sacerdote corpulento está dando un sermón a los creyentes de la ciudad. "Por Kefale, alabemos y demos gracias por este mundo maravilloso".

"Integridad, sinceridad, perdón...".', 'https://honkai-star-rail.fandom.com/es/wiki/C%C3%ADfer', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","nombre":"Augurio etéreo","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","nombre":"Augurio etéreo","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","nombre":"Gemido resonante","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","nombre":"Gemido resonante","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","nombre":"Lamento eterno","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","nombre":"Lamento eterno","cantidad":9}]}]'::jsonb),
  ('hsr-clara', 'honkai-star-rail', 'Clara', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1107.png', '5', 'Físico', 80, null, 'Tanque / DPS', 'Destrucción', 'Algo irremplazable', false, 'A vagrant girl who lives with robots. She is introverted, gentle, and has a pure heart. She wishes for all Underworlders to become a family.

A young girl raised by a robot. Her perceptiveness and tenacity are far beyond her years. For Clara, Svarog''s logical calculations are the laws of the world and are infallible. That is, until she realizes that the results from the calculations don''t always necessarily bring joy to everyone. The once shy little girl then decides to cast aside her timidness.', 'https://honkai-star-rail.fandom.com/wiki/Clara%2FLore', 'A vagrant girl who lives with robots. She is introverted, gentle, and has a pure heart. She wishes for all Underworlders to become a family.

A young girl raised by a robot. Her perceptiveness and tenacity are far beyond her years. For Clara, Svarog''s logical calculations are the laws of the world and are infallible. That is, until she realizes that the results from the calculations don''t always necessarily bring joy to everyone. The once shy little girl then decides to cast aside her timidness.', 'https://honkai-star-rail.fandom.com/wiki/Clara%2FLore', '"Registro ████/██/██ Era de la Fortificación". "Encontramos una niña pequeña en un vertedero al sureste de Villarroca". "El escáner mostró que la niña no tenía daños estructurales ni disfunciones, pero su estado mental era relativamente inestable. Se resistía a las preguntas sobre su estado y claramente quería evitar el tema". "Continuamos con los intentos de comunicación y logramos obtener alguna información". "La niña comenzó a llorar, lo que duró tres horas y siete minutos". "La niña se llama Clara, y su origen es desconocido". "Conclusión: Llevarla de vuelta a la base para observarla, y recoger más información para generar un plan de seguimiento para atenderla."', 'https://honkai-star-rail.fandom.com/es/wiki/Clara', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112011.png","nombre":"Componente antiguo","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112011.png","nombre":"Componente antiguo","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110401.png","nombre":"Dientes rotos del huargo férreo","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112012.png","nombre":"Eje antiguo","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110401.png","nombre":"Dientes rotos del huargo férreo","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112012.png","nombre":"Eje antiguo","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110401.png","nombre":"Dientes rotos del huargo férreo","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112013.png","nombre":"Motor antiguo","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110401.png","nombre":"Dientes rotos del huargo férreo","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112013.png","nombre":"Motor antiguo","cantidad":9}]}]'::jsonb),
  ('hsr-cyrene', 'honkai-star-rail', 'Cyrene', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1415.png', '4', 'Hielo', 80, null, 'Debuffer / Support', 'Memoria', 'Cono de firma de Cyrene', false, 'A meteor streaks across the night sky, stirring ripples in the river of life, shimmering with thirteen hues. Daughter of Aedes Elysiae, nurturer of the Chrysos Heir of "███," plants the Seed of Memory, letting yesterday''s flowers bloom in tomorrow —"Now, let''s write a different kind of poem together♪"

A meteor streaks across the night sky, sending ripples through the river of life, gleaming in thirteen hues. Daughter of Aedes Elysiae, Chrysos Heir who nourishes "██," sow the Seed of Memory, so that flowers of the past may bloom in tomorrow. "Now, let''s write a different kind of poem together ♪"', 'https://honkai-star-rail.fandom.com/wiki/Cyrene%2FLore', 'A meteor streaks across the night sky, stirring ripples in the river of life, shimmering with thirteen hues. Daughter of Aedes Elysiae, nurturer of the Chrysos Heir of "███," plants the Seed of Memory, letting yesterday''s flowers bloom in tomorrow —"Now, let''s write a different kind of poem together♪"

A meteor streaks across the night sky, sending ripples through the river of life, gleaming in thirteen hues. Daughter of Aedes Elysiae, Chrysos Heir who nourishes "██," sow the Seed of Memory, so that flowers of the past may bloom in tomorrow. "Now, let''s write a different kind of poem together ♪"', 'https://honkai-star-rail.fandom.com/wiki/Cyrene%2FLore', 'Un meteoro surca el cielo nocturno y agita el río de la vida, reluciendo con trece tonalidades distintas. Hija de Aedes Elysiae y nodriza de la Heredera de Crisos de "███", siembra la Semilla del Recuerdo para que las flores de ayer broten en el mañana. "Y ahora, escribamos juntos un poema diferente♪".', 'https://honkai-star-rail.fandom.com/wiki/Cyrene%2FLore', true, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","nombre":"Carne pisoteada del miedo","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","nombre":"Carne pisoteada del miedo","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110433.png","nombre":"Aleta rasgada de sirena","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","nombre":"Pecho hendido del valor","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110433.png","nombre":"Aleta rasgada de sirena","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","nombre":"Pecho hendido del valor","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110433.png","nombre":"Aleta rasgada de sirena","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","nombre":"Torso bautizado de gloria","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110433.png","nombre":"Aleta rasgada de sirena","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","nombre":"Torso bautizado de gloria","cantidad":9}]}]'::jsonb),
  ('hsr-dan-heng', 'honkai-star-rail', 'Dan Heng', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1002.png', '4', 'Viento', 80, null, 'DPS', 'Cacería', 'El silencio perdura', false, 'A cold and reserved young man who is reticent about his past. To avoid his kin, he decided to travel with the Astral Express.

A cold and reserved young man who wields a spear known as Cloud-Piercer. He acts as the Express'' guard on its long trailblazing expedition. Dan Heng never talks much about his past. In fact, he joined the Express Crew to escape from a past of his own making. But can the Express really help him outrun his past?', 'https://honkai-star-rail.fandom.com/wiki/Dan%20Heng%2FLore', 'A cold and reserved young man who is reticent about his past. To avoid his kin, he decided to travel with the Astral Express.

A cold and reserved young man who wields a spear known as Cloud-Piercer. He acts as the Express'' guard on its long trailblazing expedition. Dan Heng never talks much about his past. In fact, he joined the Express Crew to escape from a past of his own making. But can the Express really help him outrun his past?', 'https://honkai-star-rail.fandom.com/wiki/Dan%20Heng%2FLore', 'Comienza un nuevo día. No es más que otro día extremadamente normal a bordo de esta gigantesca nave. Los mercados ya abrieron, y el rocío de la mañana aún está fresco. Sin embargo, el joven que cruza la calle no había visto nunca semejante espectáculo. Incluso antes de arreglárselas para notar todas las diferencias entre la ciudad real y la descripción del libro, ya está disfrutando del calor del sol en la nuca. Era la primera vez que veía su propio cuerpo con claridad. Este cuerpo que le pertenece, el cuerpo que pertenece a este nombre actual. Cuando llegó al puerto, el soldado que lo escoltaba le quitó los últimos grilletes. Caminó hacia adelante sin mirar atrás. Podía sentir, muy débilmente, varios transeúntes, mirándolo llenos de odio. No fue hasta que la nave espacial despegó que volvió la cabeza y echó un último vistazo atrás. Realmente era una nave espacial magníficamente grandiosa, tal como decía el libro.', 'https://honkai-star-rail.fandom.com/es/wiki/Dan%20Heng', false, '[{"desde":20,"hasta":30,"creditos":3200,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":4}]},{"desde":30,"hasta":40,"creditos":6400,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":8}]},{"desde":40,"hasta":50,"creditos":12800,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110405.png","nombre":"Ojo del vendaval","cantidad":2},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":5}]},{"desde":50,"hasta":60,"creditos":32000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110405.png","nombre":"Ojo del vendaval","cantidad":5},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":8}]},{"desde":60,"hasta":70,"creditos":64000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110405.png","nombre":"Ojo del vendaval","cantidad":15},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":5}]},{"desde":70,"hasta":80,"creditos":128000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110405.png","nombre":"Ojo del vendaval","cantidad":28},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":7}]}]'::jsonb),
  ('hsr-imbibitor-lunae', 'honkai-star-rail', 'Dan Heng (Imbibitor Lunae)', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1213.png', '5', 'Imaginario', 80, null, 'DPS', 'Destrucción', 'Más brillante que el sol', false, 'Dan Heng''s true form from his Vidyadhara lineage carries the residual power left behind by his past incarnation, the Imbibitor Lunae. Upon accepting the majestic horns atop his crown, he must accept all the merits and faults attributed to that sinner.

Dan Heng''s true Vidyadhara form, revealed after accepting the residual powers from the previous reincarnation of "Imbibitor Lunae." Upon accepting the majestic horned crown atop his forehead, he must accept all the merits and faults attributed to that person. However, he was never himself.', 'https://honkai-star-rail.fandom.com/wiki/Dan%20Heng%20%E2%80%A2%20Imbibitor%20Lunae%2FLore', 'Dan Heng''s true form from his Vidyadhara lineage carries the residual power left behind by his past incarnation, the Imbibitor Lunae. Upon accepting the majestic horns atop his crown, he must accept all the merits and faults attributed to that sinner.

Dan Heng''s true Vidyadhara form, revealed after accepting the residual powers from the previous reincarnation of "Imbibitor Lunae." Upon accepting the majestic horned crown atop his forehead, he must accept all the merits and faults attributed to that person. However, he was never himself.', 'https://honkai-star-rail.fandom.com/wiki/Dan%20Heng%20%E2%80%A2%20Imbibitor%20Lunae%2FLore', 'Comienza un nuevo día. No es más que otro día extremadamente normal a bordo de esta gigantesca nave. Los mercados ya abrieron, y el rocío de la mañana aún está fresco. Sin embargo, el joven que cruza la calle no había visto nunca semejante espectáculo. Incluso antes de arreglárselas para notar todas las diferencias entre la ciudad real y la descripción del libro, ya está disfrutando del calor del sol en la nuca. Era la primera vez que veía su propio cuerpo con claridad. Este cuerpo que le pertenece, el cuerpo que pertenece a este nombre actual. Cuando llegó al puerto, el soldado que lo escoltaba le quitó los últimos grilletes. Caminó hacia adelante sin mirar atrás. Podía sentir, muy débilmente, varios transeúntes, mirándolo llenos de odio. No fue hasta que la nave espacial despegó que volvió la cabeza y echó un último vistazo atrás. Realmente era una nave espacial magníficamente grandiosa, tal como decía el libro.', 'https://honkai-star-rail.fandom.com/es/wiki/Dan%20Heng', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110417.png","nombre":"Edicto de la contención","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110417.png","nombre":"Edicto de la contención","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110417.png","nombre":"Edicto de la contención","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110417.png","nombre":"Edicto de la contención","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":9}]}]'::jsonb),
  ('hsr-permanser-terrae', 'honkai-star-rail', 'Dan Heng (Permanser Terrae)', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1414.png', '5', 'Físico', 80, null, 'Tanque', 'Conservación', 'Cono de firma de Permanser Terrae', false, 'The chest of Georios, the body of the fallen dragon supporting the shattered earth, enduring millennia of pain. Dan Heng, the Nameless and the Chrysos Heir who guards the Earth''s Coreflame, steadies the world before it falls and guides all life across the land to a new home beyond. Rivers flow to the sea, mountains echo in harmony, and the eternal path stretches ten thousand miles.', 'https://honkai-star-rail.fandom.com/wiki/Dan%20Heng%20%E2%80%A2%20Permansor%20Terrae%2FLore', 'The chest of Georios, the body of the fallen dragon supporting the shattered earth, enduring millennia of pain. Dan Heng, the Nameless and the Chrysos Heir who guards the Earth''s Coreflame, steadies the world before it falls and guides all life across the land to a new home beyond. Rivers flow to the sea, mountains echo in harmony, and the eternal path stretches ten thousand miles.', 'https://honkai-star-rail.fandom.com/wiki/Dan%20Heng%20%E2%80%A2%20Permansor%20Terrae%2FLore', 'Comienza un nuevo día. No es más que otro día extremadamente normal a bordo de esta gigantesca nave. Los mercados ya abrieron, y el rocío de la mañana aún está fresco. Sin embargo, el joven que cruza la calle no había visto nunca semejante espectáculo. Incluso antes de arreglárselas para notar todas las diferencias entre la ciudad real y la descripción del libro, ya está disfrutando del calor del sol en la nuca. Era la primera vez que veía su propio cuerpo con claridad. Este cuerpo que le pertenece, el cuerpo que pertenece a este nombre actual. Cuando llegó al puerto, el soldado que lo escoltaba le quitó los últimos grilletes. Caminó hacia adelante sin mirar atrás. Podía sentir, muy débilmente, varios transeúntes, mirándolo llenos de odio. No fue hasta que la nave espacial despegó que volvió la cabeza y echó un último vistazo atrás. Realmente era una nave espacial magníficamente grandiosa, tal como decía el libro.', 'https://honkai-star-rail.fandom.com/es/wiki/Dan%20Heng', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","nombre":"Carne pisoteada del miedo","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","nombre":"Carne pisoteada del miedo","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","nombre":"Pecho hendido del valor","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","nombre":"Pecho hendido del valor","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","nombre":"Torso bautizado de gloria","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","nombre":"Torso bautizado de gloria","cantidad":9}]}]'::jsonb),
  ('hsr-dr-ratio', 'honkai-star-rail', 'Dr. Ratio', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1305.png', '5', 'Imaginario', 80, null, 'DPS', 'Cacería', 'El bautismo del pensamiento puro', false, 'Member of the Intelligentsia Guild. Eccentric temperament, sharp-tongued but with an elegant demeanor. The face under the strange alabaster head sculpture is apparently unexpectedly handsome.

A candid and self-assured Intelligentsia Guild member, who often conceals his appearance with a strange plaster sculpture. He demonstrated unparalleled intelligence and talent since his youth, but now refers to himself as a "Mundanite." Firmly believing that intellect and creativity are not confined to geniuses, he seeks to distribute knowledge to the entire universe to cure the persistent disease named ignorance.', 'https://honkai-star-rail.fandom.com/wiki/Dr.%20Ratio%2FLore', 'Member of the Intelligentsia Guild. Eccentric temperament, sharp-tongued but with an elegant demeanor. The face under the strange alabaster head sculpture is apparently unexpectedly handsome.

A candid and self-assured Intelligentsia Guild member, who often conceals his appearance with a strange plaster sculpture. He demonstrated unparalleled intelligence and talent since his youth, but now refers to himself as a "Mundanite." Firmly believing that intellect and creativity are not confined to geniuses, he seeks to distribute knowledge to the entire universe to cure the persistent disease named ignorance.', 'https://honkai-star-rail.fandom.com/wiki/Dr.%20Ratio%2FLore', 'Veritas Ratio, que se hace llamar "Dr. Ratio", es tan controvertido como sus investigaciones. Existen al menos ocho documentales sobre las legendarias hazañas de Ratio y más de una docena de memorias sobre él en su mundo natal. Hay numerosos comentarios, pero ninguno de ellos ofrece un punto de vista persuasivo. Para llenar ese vacío, visité al profesor Rond, que ejerció una gran influencia en la juventud de Ratio. El profesor Rond tenía dificultades para hablar debido a su avanzada edad, pero no pudo contener su emoción al mencionar el nombre de Ratio. Con la ayuda de su familia y sus alumnos, conseguí una carta de recomendación amarillenta pero bien conservada.

 "Al respetado comité de admisión de la Universidad de Veritas Prime:

Soy Rond, Profesor Emérito del Departamento de Matemáticas de la Universidad Galáctica Libre.', 'https://honkai-star-rail.fandom.com/es/wiki/Dr.%20Ratio', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","nombre":"Instinto del ladrón","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","nombre":"Instinto del ladrón","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110417.png","nombre":"Edicto de la contención","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","nombre":"Ambición distorsionada","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110417.png","nombre":"Edicto de la contención","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","nombre":"Ambición distorsionada","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110417.png","nombre":"Edicto de la contención","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","nombre":"Voluntad de conquista","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110417.png","nombre":"Edicto de la contención","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","nombre":"Voluntad de conquista","cantidad":9}]}]'::jsonb),
  ('hsr-evanescia', 'honkai-star-rail', 'Evanescia', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1505.png', '5', 'Físico', null, null, null, 'Júbilo', null, false, null, null, null, null, null, null, false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","nombre":"Crayón de la inocencia","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","nombre":"Crayón de la inocencia","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","nombre":"Pluma creasueños","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","nombre":"Pluma creasueños","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","nombre":"Pincel de los sueños","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","nombre":"Pincel de los sueños","cantidad":9}]}]'::jsonb),
  ('hsr-evernight', 'honkai-star-rail', 'Evernight', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1413.png', '5', 'Hielo', 80, null, 'Debuffer (Control)', 'Memoria', 'Cono de firma de Evernight', false, 'In the Memory Zone secluded from the world, candlelight reflects the past, silently extinguishing in the mist. Evernight, child of Remembrance emerging from those shadows, the Chrysos Heir who conceals the Coreflame of "Time," raises the waves of "Oblivion" to protect the wishes of those in the mirror "Don''t worry, I will guard the path of Trailblaze for you... at any cost. ♭"', 'https://honkai-star-rail.fandom.com/wiki/Evernight%2FLore', 'In the Memory Zone secluded from the world, candlelight reflects the past, silently extinguishing in the mist. Evernight, child of Remembrance emerging from those shadows, the Chrysos Heir who conceals the Coreflame of "Time," raises the waves of "Oblivion" to protect the wishes of those in the mirror "Don''t worry, I will guard the path of Trailblaze for you... at any cost. ♭"', 'https://honkai-star-rail.fandom.com/wiki/Evernight%2FLore', '"Querida Siete de Marzo:

Verte es como ver los primeros rayos del amanecer, me llena de expectación. Quizás fui demasiado impaciente al aparecer así ante ti, pero por suerte las feromonas te hicieron creer que no era más que una ilusión.

La última vez que estuvimos así de cerca fue cuando intentabas explorar el pasado. Comparado con ese momento, parece que has madurado un poco más. Tú y tus compañeros —(Trazacaminos), Dan Heng, Himeko, Welt y ese caballeroso amigo— lucharon juntos en perfecta sincronía... ♭ Incluso a mí me costó un poco de esfuerzo enfrentarme a semejante grupo. ♭

La memoria es algo maravilloso... Sin que nos hayamos dado cuenta, tu viaje ya lleva mucho tiempo en curso.

Aún recuerdo los innumerables ojos avariciosos que, tras las estrellas titilantes, espiaban este cuerpo y codiciaban este secreto.', 'https://honkai-star-rail.fandom.com/es/wiki/Larganoche', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","nombre":"Augurio etéreo","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","nombre":"Augurio etéreo","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110433.png","nombre":"Aleta rasgada de sirena","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","nombre":"Gemido resonante","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110433.png","nombre":"Aleta rasgada de sirena","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","nombre":"Gemido resonante","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110433.png","nombre":"Aleta rasgada de sirena","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","nombre":"Lamento eterno","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110433.png","nombre":"Aleta rasgada de sirena","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","nombre":"Lamento eterno","cantidad":9}]}]'::jsonb),
  ('hsr-feixiao', 'honkai-star-rail', 'Feixiao', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1220.png', '5', 'Viento', 80, null, 'DPS', 'Cacería', 'Salgo a cazar', false, 'The Xianzhou Yaoqing''s Merlin''s Claw and one of the Seven Arbiter-Generals. Unconventional and straightforward, she exudes effortless charm. She is skilled in all forms of martial arts and has honed herself into a supreme weapon. She is widely adored by Xianzhou soldiers and civilians alike as "The Vanquishing General." However, she bears the burden of the Moon Rage affliction. If she were to hunt down all the abominations in her limited lifetime — then the only enemy Feixiao has would be herself.', 'https://honkai-star-rail.fandom.com/wiki/Feixiao%2FLore', 'The Xianzhou Yaoqing''s Merlin''s Claw and one of the Seven Arbiter-Generals. Unconventional and straightforward, she exudes effortless charm. She is skilled in all forms of martial arts and has honed herself into a supreme weapon. She is widely adored by Xianzhou soldiers and civilians alike as "The Vanquishing General." However, she bears the burden of the Moon Rage affliction. If she were to hunt down all the abominations in her limited lifetime — then the only enemy Feixiao has would be herself.', 'https://honkai-star-rail.fandom.com/wiki/Feixiao%2FLore', 'Un atisbo de sangre y malestar flota en el aire.

"Neergul...". Ella da unas suaves palmaditas a su temblorosa acompañante, "Presiento... Una oportunidad de libertad. Esta noche es la noche". "Saran, los cuerpos de los tres esclavos raposianos que intentaron escapar siguen colgados en las puertas...". "No, esta noche es diferente". Levanta la cabeza y mira a lo lejos mientras una luz gigante recorre lentamente el cielo. "Esta noche, habrá estrellas fugaces". Toma la mano de su acompañante. "Está bien. Solo sigue mirando hacia adelante y no mires atrás".

Bajo la luz fría y brillante de las estrellas fugaces, dos delicadas siluetas corren por las interminables llanuras. El aire ensangrentado azota sus rostros mientras los escalofriantes aullidos de los lobos despiertan sin cesar el miedo enterrado profundamente en su sangre. Sin embargo, ella nunca dudó de que escaparían de la persecución de la manada borisin.', 'https://honkai-star-rail.fandom.com/es/wiki/Feixiao', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110425.png","nombre":"Copa de la era embriagada","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110425.png","nombre":"Copa de la era embriagada","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110425.png","nombre":"Copa de la era embriagada","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110425.png","nombre":"Copa de la era embriagada","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":9}]}]'::jsonb),
  ('hsr-firefly', 'honkai-star-rail', 'Firefly (Sam)', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1310.png', '5', 'Fuego', 80, null, 'DPS (Ruptura)', 'Destrucción', 'Donde los sueños descansan', false, 'A member of the Stellaron Hunters, clad in a set of mechanized armor known as "SAM." Her character is marked by unwavering loyalty and steely resolve. Engineered as a weapon against the Swarm, she experiences accelerated growth, but a tragically shortened lifespan. She joined the Stellaron Hunters in a quest for a chance at "life," seeking to defy her fated demise.', 'https://honkai-star-rail.fandom.com/wiki/Firefly%2FLore', 'A member of the Stellaron Hunters, clad in a set of mechanized armor known as "SAM." Her character is marked by unwavering loyalty and steely resolve. Engineered as a weapon against the Swarm, she experiences accelerated growth, but a tragically shortened lifespan. She joined the Stellaron Hunters in a quest for a chance at "life," seeking to defy her fated demise.', 'https://honkai-star-rail.fandom.com/wiki/Firefly%2FLore', 'Miembro de los Cazadores de Estelaron, cubierta por una armadura mecanizada conocida como "SAM". La definen una lealtad inquebrantable y una determinación de acero. Concebida como arma contra el Enjambre, experimenta un crecimiento acelerado a cambio de una vida trágicamente corta. Se unió a los Cazadores de Estelaron buscando una oportunidad de "vivir" y desafiar así el final que tiene escrito.', 'https://honkai-star-rail.fandom.com/wiki/Firefly%2FLore', true, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","nombre":"Jirones de pensamientos","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","nombre":"Jirones de pensamientos","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","nombre":"Fragmento de impresiones","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","nombre":"Fragmento de impresiones","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","nombre":"Fragmento de deseos","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","nombre":"Fragmento de deseos","cantidad":9}]}]'::jsonb),
  ('hsr-fu-xuan', 'honkai-star-rail', 'Fu Xuan', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1208.png', '5', 'Cuántico', 80, null, 'Tanque / Buffer', 'Conservación', 'Ella ya ha cerrado los ojos', false, 'Head of the Divination Commission on the Luofu. The person who uses the third eye and Matrix of Prescience to foretell the route of Xianzhou and the outcomes of events.

The head of the Xianzhou Luofu''s Divination Commission and a confident, no-nonsense sage. Using her third eye and the Matrix of Prescience, Fu Xuan calculates the Xianzhou''s navigational route and predicts the fortune of future events. She firmly believes that everything she does is the "best solution" for the situation. Fu Xuan is waiting for the general''s promised "abdication." However, that day still seems... very far away.', 'https://honkai-star-rail.fandom.com/wiki/Fu%20Xuan%2FLore', 'Head of the Divination Commission on the Luofu. The person who uses the third eye and Matrix of Prescience to foretell the route of Xianzhou and the outcomes of events.

The head of the Xianzhou Luofu''s Divination Commission and a confident, no-nonsense sage. Using her third eye and the Matrix of Prescience, Fu Xuan calculates the Xianzhou''s navigational route and predicts the fortune of future events. She firmly believes that everything she does is the "best solution" for the situation. Fu Xuan is waiting for the general''s promised "abdication." However, that day still seems... very far away.', 'https://honkai-star-rail.fandom.com/wiki/Fu%20Xuan%2FLore', 'Años después, Fu Xuan siempre recordaría el día en que le permitieron entrar en la biblioteca para hacer preguntas.

"¿En qué piensas?". Un anciano ciego con gafas oscuras y un bastón en la mano movía los ojos de un lado a otro esperando su respuesta.

"¿Todas nuestras decisiones están predeterminadas? Entonces, si mis cálculos hubieran sido más precisos en ese momento, incluso solo una millonésima más precisos, ¿podría haber tomado la decisión correcta para que no tuvieran que marcharse?". La joven entrecerró los ojos, aparentemente preguntando y respondiéndose ella misma.

"En todo momento estamos en el centro de un laberinto trazado por nuestras propias huellas". El anciano ciego golpeó ligeramente el suelo con su bastón. "No puedo darte las respuestas. Solo puedo darte las preguntas... y la capacidad de ver el problema. Teniendo en cuenta el viaje que te trajo aquí, lo que buscas probablemente no es una respuesta".

"Entonces dame el "ojo".', 'https://honkai-star-rail.fandom.com/es/wiki/Fu%20Xuan', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110416.png","nombre":"Clavo del simio","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110416.png","nombre":"Clavo del simio","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110416.png","nombre":"Clavo del simio","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110416.png","nombre":"Clavo del simio","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":9}]}]'::jsonb),
  ('hsr-fugue', 'honkai-star-rail', 'Fugue (Tingyun 5⭐)', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1225.png', '5', 'Fuego', 80, null, 'Debuffer / Buffer', 'Nihilidad', 'El largo camino a casa', false, 'A tactful foxian girl, whose appearance, name, and identity have all been stolen. The fates have left her a thread of chance at survival, yet the brand of Destruction still writhes with anticipation. The one in a fugue who has experienced life and death and is given a new life... when would she be able to return home?

The former chief representative of the Whistling Flames merchant guild in the Sky-Faring Commission who nearly lost her life in a strange and catastrophic incident on her return journey. Her face, name, and identity were stolen by the one who orchestrated it all. Yet, by a twist of fate, a sliver of hope remained, and from the aftermath of the Destruction, she reclaimed her life. Now, she goes by the name "Fugue." Whether it be the bitterness of never returning home or the allure of wandering through the starry seas that drives her, one thing is certain — she has risen once more and set out on her path anew.', 'https://honkai-star-rail.fandom.com/wiki/Fugue%2FLore', 'A tactful foxian girl, whose appearance, name, and identity have all been stolen. The fates have left her a thread of chance at survival, yet the brand of Destruction still writhes with anticipation. The one in a fugue who has experienced life and death and is given a new life... when would she be able to return home?

The former chief representative of the Whistling Flames merchant guild in the Sky-Faring Commission who nearly lost her life in a strange and catastrophic incident on her return journey. Her face, name, and identity were stolen by the one who orchestrated it all. Yet, by a twist of fate, a sliver of hope remained, and from the aftermath of the Destruction, she reclaimed her life. Now, she goes by the name "Fugue." Whether it be the bitterness of never returning home or the allure of wandering through the starry seas that drives her, one thing is certain — she has risen once more and set out on her path anew.', 'https://honkai-star-rail.fandom.com/wiki/Fugue%2FLore', 'El brazalete de jade que una vez la protegió yacía hecho añicos, la campana de bendición había caído al barro, y el abanico plegable vibrantemente adornado se había hecho cenizas. Solo podía observar cómo el fuego fantasmal de la oscuridad consumía todo lo que había poseído, reduciéndolo a llamas y ruinas.

Por un momento, solo se lamentó por quedarse a un paso por detrás de la vida. "Acabo de cerrar un gran trato con ese comerciante itinerante... Una oportunidad desperdiciada...". "Todo ese esfuerzo por esta cola tan bien cuidada, ahora se reduce a nada...". "Ni siquiera podré cumplir mi promesa... de llevarles regalos a todos...". Un millar de pensamientos se agolpaban en su mente, pero su cuerpo permanecía quieto, inmóvil, mientras las lágrimas se acumulaban silenciosamente en las comisuras de sus ojos.

Los recuerdos parpadeaban y se apagaban como la luz de una vela moribunda. "Cuánto desearía ver a la señora Yukong surcando el cielo con el arco que le compré...', 'https://honkai-star-rail.fandom.com/es/wiki/Fugue', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110412.png","nombre":"Hoja de acero sobrecalentado","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110412.png","nombre":"Hoja de acero sobrecalentado","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110412.png","nombre":"Hoja de acero sobrecalentado","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110412.png","nombre":"Hoja de acero sobrecalentado","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":9}]}]'::jsonb),
  ('hsr-gallagher', 'honkai-star-rail', 'Gallagher', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1301.png', '4', 'Fuego', 80, null, 'Support (Healer)', 'Abundancia', 'Quédate (Recomendado)', false, 'A security officer of the Bloodhound Family at Penacony. He is always courteous toward visiting guests but keeps his vigilance about him. He seems to carry a weight of a complicated past, yet he never voluntarily divulges any details.

A security officer from the Bloodhound Family in Penacony. He is also a slovenly and indolent drinksmith. Though unorganized in apparel and casual in how he makes his drinks, he is always courteous toward visiting guests but keeps his vigilance about him. He seems to carry a weight of a complicated past, yet he never voluntarily divulges any details.', 'https://honkai-star-rail.fandom.com/wiki/Gallagher%2FLore', 'A security officer of the Bloodhound Family at Penacony. He is always courteous toward visiting guests but keeps his vigilance about him. He seems to carry a weight of a complicated past, yet he never voluntarily divulges any details.

A security officer from the Bloodhound Family in Penacony. He is also a slovenly and indolent drinksmith. Though unorganized in apparel and casual in how he makes his drinks, he is always courteous toward visiting guests but keeps his vigilance about him. He seems to carry a weight of a complicated past, yet he never voluntarily divulges any details.', 'https://honkai-star-rail.fandom.com/wiki/Gallagher%2FLore', '"Olor a tabaco, caramelos y champú barato... Desprende el típico olor de un soltero de mediana edad. Aunque su ropa es pulcra, siempre está arrugada y muestra falta de estilo. Tampoco demuestra interés alguno en cuidar de su aspecto. No tiene muchos amigos, y su pasatiempo favorito después del trabajo es disfrutar de unas copas del Especial Dulces Sueños. Siempre se sienta en el mismo sitio, con la misma bebida y con los mismos camareros... Nunca ha cambiado en más de una década.

Aun así es un hombre que se ganó la admiración y el respeto de los miembros de la familia Sabueso, lo que probablemente esté relacionado con esa cicatriz grabada en su rostro. En un dulce sueño prácticamente desprovisto de accidentes, una fea cicatriz es un raro honor para un oficial de seguridad, símbolo de antigüedad y prestigio.

Cuando se enfrenta a un caso, lo primero que hace es desenvolver un caramelo y llevárselo a la boca.', 'https://honkai-star-rail.fandom.com/es/wiki/Gallagher', false, '[{"desde":20,"hasta":30,"creditos":3200,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","nombre":"Componente del acumulador de sueños","cantidad":4}]},{"desde":30,"hasta":40,"creditos":6400,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","nombre":"Componente del acumulador de sueños","cantidad":8}]},{"desde":40,"hasta":50,"creditos":12800,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":2},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","nombre":"Válvula del flujo de sueños","cantidad":5}]},{"desde":50,"hasta":60,"creditos":32000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":5},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","nombre":"Válvula del flujo de sueños","cantidad":8}]},{"desde":60,"hasta":70,"creditos":64000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":15},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","nombre":"Motor creasueños","cantidad":5}]},{"desde":70,"hasta":80,"creditos":128000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":28},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","nombre":"Motor creasueños","cantidad":7}]}]'::jsonb),
  ('hsr-gepard', 'honkai-star-rail', 'Gepard', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1104.png', '5', 'Hielo', 80, null, 'Tanque', 'Conservación', 'El momento de la victoria', false, 'A captain in the Silvermane Guards and an outstanding warrior of Belobog. He is meticulous and vigilant to the core and is always true to himself.

The honorable and upstanding captain of the Silvermane Guards who bears the noble Landau family name. In the frost-whipped city of Belobog, life can still go on in normality... This is in no small part thanks to Gepard and his Silvermane Guards who protect the peace of everyday life.', 'https://honkai-star-rail.fandom.com/wiki/Gepard%2FLore', 'A captain in the Silvermane Guards and an outstanding warrior of Belobog. He is meticulous and vigilant to the core and is always true to himself.

The honorable and upstanding captain of the Silvermane Guards who bears the noble Landau family name. In the frost-whipped city of Belobog, life can still go on in normality... This is in no small part thanks to Gepard and his Silvermane Guards who protect the peace of everyday life.', 'https://honkai-star-rail.fandom.com/wiki/Gepard%2FLore', 'El joven capitán estaba en lo alto de la muralla norte.

Contempló los páramos blancos que tenía ante sí, y observó a los extraños seres del Fragmentum que formaban un enjambre inquieto en la distancia. Vio a la intrépida Guardia Crinargenta alineada en formación para vigilar la ciudad, como un parapeto defensivo.

Esta era su posición original. Cuando aún era un humilde soldado raso, había jurado ser el escudo más fuerte de Belobog y se comprometió a morir con sus camaradas, incluso como capitán. No se trata de una broma de la Guardia Crinargenta, porque Qlipoth es testigo de este juramento.

Sin embargo, justo en ese momento, no estaba donde debía estar, y todo era por la petición de la Guardiana Suprema.

¿En qué estaba pensando exactamente la Guardiana Suprema? El joven capitán no tenía ni idea, pero pronto se obligó a centrarse en el conflicto que tenía entre manos.

"Recuerda, Gepard Landau". "La duda engendra arrogancia, y la duda engendra maldad.', 'https://honkai-star-rail.fandom.com/es/wiki/Gepard', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","nombre":"Pin del guardia","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","nombre":"Pin del guardia","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110403.png","nombre":"Cuerno de nieve","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","nombre":"Insignia del guardia","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110403.png","nombre":"Cuerno de nieve","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","nombre":"Insignia del guardia","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110403.png","nombre":"Cuerno de nieve","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","nombre":"Medalla del guardia","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110403.png","nombre":"Cuerno de nieve","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","nombre":"Medalla del guardia","cantidad":9}]}]'::jsonb),
  ('hsr-gilgamesh', 'honkai-star-rail', 'Gilgamesh (Collab)', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1509.png', '5', 'Imaginario', 80, null, 'DPS', 'Erudición', 'Cono de evento/firma', false, 'The King of Heroes from the dawn of human history, hailing from a world beyond the stars. Possessing a nature two-thirds divine and one-third mortal, he claims a natural-born prerogative to rule over all of creation.

The King of Heroes from the dawn of human history, hailing from a world beyond the stars. Being two-thirds divine and one-third mortal, he claims a natural-born prerogative to rule over all of creation. Today, as ever, his boisterous laughter echoed through the heavens... until a certain goddess and eternal rival dragged him into a foreign realm. Now, he sets forth once more to reclaim all that belongs to a king.', 'https://honkai-star-rail.fandom.com/wiki/Gilgamesh%2FLore', 'The King of Heroes from the dawn of human history, hailing from a world beyond the stars. Possessing a nature two-thirds divine and one-third mortal, he claims a natural-born prerogative to rule over all of creation.

The King of Heroes from the dawn of human history, hailing from a world beyond the stars. Being two-thirds divine and one-third mortal, he claims a natural-born prerogative to rule over all of creation. Today, as ever, his boisterous laughter echoed through the heavens... until a certain goddess and eternal rival dragged him into a foreign realm. Now, he sets forth once more to reclaim all that belongs to a king.', 'https://honkai-star-rail.fandom.com/wiki/Gilgamesh%2FLore', 'El Rey de los Héroes de los albores de la historia humana, procedente de un mundo más allá de las estrellas. Con una naturaleza dos tercios divina y un tercio mortal, reclama como derecho de nacimiento el gobierno sobre toda la creación. Hoy, como siempre, su risa estruendosa resonaba por los cielos... hasta que cierta diosa y eterna rival lo arrastró a un reino ajeno. Ahora se pone en marcha de nuevo para reclamar todo aquello que pertenece a un rey.', 'https://honkai-star-rail.fandom.com/wiki/Gilgamesh%2FLore', true, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110434.png","nombre":"Rasgueo tormentoso","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110434.png","nombre":"Rasgueo tormentoso","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110434.png","nombre":"Rasgueo tormentoso","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110434.png","nombre":"Rasgueo tormentoso","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":9}]}]'::jsonb),
  ('hsr-guinaifen', 'honkai-star-rail', 'Guinaifen', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1210.png', '4', 'Fuego', 80, null, 'Sub-DPS / Debuffer (DoT)', 'Nihilidad', 'Las miradas del pasado (Recomendado)', false, 'A performance artist visiting the Xianzhou Luofu — in other words, a street performer. She''s chasing a new life on the Luofu when not concerned with food and shelter.

An outworlder who ended up residing on the Xianzhou by accident. She is now a passionate and vivacious street performer. With her real name being Guinevere, Guinaifen is the Xianzhou name given to her by her good friend Sushang. Faced with a whole new life on the Luofu and relying on her adoration of Xianzhou culture, Guinaifen quickly learned skills that would keep her clothed and fed — such as slurping noodles in a handstand, smashing slabs without harming the people it was placed upon, catching bullets with bare hands, and so on.', 'https://honkai-star-rail.fandom.com/wiki/Guinaifen%2FLore', 'A performance artist visiting the Xianzhou Luofu — in other words, a street performer. She''s chasing a new life on the Luofu when not concerned with food and shelter.

An outworlder who ended up residing on the Xianzhou by accident. She is now a passionate and vivacious street performer. With her real name being Guinevere, Guinaifen is the Xianzhou name given to her by her good friend Sushang. Faced with a whole new life on the Luofu and relying on her adoration of Xianzhou culture, Guinaifen quickly learned skills that would keep her clothed and fed — such as slurping noodles in a handstand, smashing slabs without harming the people it was placed upon, catching bullets with bare hands, and so on.', 'https://honkai-star-rail.fandom.com/wiki/Guinaifen%2FLore', 'Hola, hola... ¿Me oyen? ¡Buenas noches, familia! Les doy la bienvenida al directo de la Pequeña Gui...

¡Gracias GranFlor_49886 por el super chat! "Pequeña Gui, hace un par de semanas que no haces ningún directo. ¿Ya no te tomas esto en serio?". ¡De ninguna manera! Estoy pasando por muchas cosas en mi vida en este momento y sí, hace tiempo que no hago ningún directo. Lo siento... De hecho, todo lo que he estado viviendo es bastante interesante. Hablaré de ello en otro momento.

Hoy, como escribí en el título del directo, es la "¡Noche de música! ¡La Pequeña Gui cantará música folclórica de Xianzhou!".

En fin, creo que cosas como las acrobacias es mejor hacerlas fuera de línea, así que en este directo voy a interpretar música folclórica. Solo estoy tanteando el terreno... Si les gusta, ¡recuerden dar me gusta, suscribirse y compartir! Si envían un regalo o un super chat, ¡participarán en el sorteo de premios de este directo!

¡Gracias, MegaMalteada, por el superchat!', 'https://honkai-star-rail.fandom.com/es/wiki/Guinaifen', false, '[{"desde":20,"hasta":30,"creditos":3200,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":4}]},{"desde":30,"hasta":40,"creditos":6400,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":8}]},{"desde":40,"hasta":50,"creditos":12800,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110412.png","nombre":"Hoja de acero sobrecalentado","cantidad":2},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":5}]},{"desde":50,"hasta":60,"creditos":32000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110412.png","nombre":"Hoja de acero sobrecalentado","cantidad":5},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":8}]},{"desde":60,"hasta":70,"creditos":64000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110412.png","nombre":"Hoja de acero sobrecalentado","cantidad":15},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":5}]},{"desde":70,"hasta":80,"creditos":128000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110412.png","nombre":"Hoja de acero sobrecalentado","cantidad":28},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":7}]}]'::jsonb),
  ('hsr-hanya', 'honkai-star-rail', 'Hanya', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1215.png', '4', 'Físico', 80, null, 'Buffer', 'Armonía', 'Bajo el cielo azul', false, 'One of the judges of the Xianzhou Luofu''s Ten-Lords Commission. Ordained by the Ten-Lords and wielding the authority of the Oracle Brush, she reads the multitudes of human sins and transgressions, then issues punishments and karmic retribution.

One of the judges of the Ten-Lords Commission on the Luofu. She is in charge of "interrogation" among the four judges of detention, interrogation, incarceration, and punishment. She is in charge of discerning the sins of criminals and using her Oracle Brush to write down karmic punishments to be meted out. Since her daily work relies heavily on oneiromancy, she has been constantly struck by a tremendous influx of mara-tainted karmic information and grown detached from worldly matters. Only when in the presence of her sister, Xueyi, does she reveal a glimpse of her tender nature.', 'https://honkai-star-rail.fandom.com/wiki/Hanya%2FLore', 'One of the judges of the Xianzhou Luofu''s Ten-Lords Commission. Ordained by the Ten-Lords and wielding the authority of the Oracle Brush, she reads the multitudes of human sins and transgressions, then issues punishments and karmic retribution.

One of the judges of the Ten-Lords Commission on the Luofu. She is in charge of "interrogation" among the four judges of detention, interrogation, incarceration, and punishment. She is in charge of discerning the sins of criminals and using her Oracle Brush to write down karmic punishments to be meted out. Since her daily work relies heavily on oneiromancy, she has been constantly struck by a tremendous influx of mara-tainted karmic information and grown detached from worldly matters. Only when in the presence of her sister, Xueyi, does she reveal a glimpse of her tender nature.', 'https://honkai-star-rail.fandom.com/wiki/Hanya%2FLore', 'El ataúd colosal, que parece un recipiente desolado perdido en una tormenta, se balancea en medio de las turbulentas corrientes del océano de la consciencia. Olas de ira, añoranza, odio, miedo y cansancio chocan contra ella como aluviones grises, que la empujan de un reino turbulento a otro.

Como un alma ahogada, por fin suelta su individualidad y se diluye en el infinito océano del caos...

Hubo un tiempo en que fue oficial de la Comisión de Administración del Territorio, tenía montañas de deberes mundanos y aspiraba a un ascenso.', 'https://honkai-star-rail.fandom.com/es/wiki/Hanya', false, '[{"desde":20,"hasta":30,"creditos":3200,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":4}]},{"desde":30,"hasta":40,"creditos":6400,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":8}]},{"desde":40,"hasta":50,"creditos":12800,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110411.png","nombre":"Pase del inframundo","cantidad":2},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":5}]},{"desde":50,"hasta":60,"creditos":32000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110411.png","nombre":"Pase del inframundo","cantidad":5},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":8}]},{"desde":60,"hasta":70,"creditos":64000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110411.png","nombre":"Pase del inframundo","cantidad":15},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":5}]},{"desde":70,"hasta":80,"creditos":128000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110411.png","nombre":"Pase del inframundo","cantidad":28},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":7}]}]'::jsonb),
  ('hsr-herta', 'honkai-star-rail', 'Herta', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1013.png', '4', 'Hielo', 80, null, 'Sub-DPS', 'Erudición', 'El nacimiento del yo', false, 'Member 83 of the Genius Society. The real master of the space station. An incredibly intelligent yet unsympathetic scientist.

true master. As the human with the highest IQ on the Blue, she only does what she''s interested in, dropping projects the moment she loses interest — the best example being the space station. She typically appears in the form of a remote-controlled puppet. "It''s about seventy percent similar to how I looked as a child." — Herta', 'https://honkai-star-rail.fandom.com/wiki/Herta%2FLore', 'Member 83 of the Genius Society. The real master of the space station. An incredibly intelligent yet unsympathetic scientist.

true master. As the human with the highest IQ on the Blue, she only does what she''s interested in, dropping projects the moment she loses interest — the best example being the space station. She typically appears in the form of a remote-controlled puppet. "It''s about seventy percent similar to how I looked as a child." — Herta', 'https://honkai-star-rail.fandom.com/wiki/Herta%2FLore', 'Los manuscritos de la señora Herta son activos muy valiosos.

Su principal rareza no radica en que la señora Herta apenas se molesta nunca en poner la pluma sobre el papel, sino en que, para una genio como ella, nada es digno de ser conservado por escrito.

Una investigación científica que a los investigadores normales les llevaría diez años, o incluso toda una vida, podría iluminar un ámbito de investigación totalmente nuevo. Pero para Herta, es tan aburrido como una luz LED al azar. ¿Quién perdería el tiempo tratando de registrar sistemáticamente asuntos tan triviales?

No se trata solo de la señora Herta: cualquier trabajo escrito por un miembro del Círculo de Genios es un tesoro de valor incalculable. Sin embargo, Herta es más generosa y comprensiva con la gente normal. Deja sus papeles en lugares aleatorios de la Estación Espacial y permite a los investigadores estudiar los objetos raros que recopiló.

Por supuesto, todos sabemos que no es que la señora Herta sea perezosa.', 'https://honkai-star-rail.fandom.com/es/wiki/Herta', false, '[{"desde":20,"hasta":30,"creditos":3200,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":4}]},{"desde":30,"hasta":40,"creditos":6400,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":8}]},{"desde":40,"hasta":50,"creditos":12800,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110403.png","nombre":"Cuerno de nieve","cantidad":2},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":5}]},{"desde":50,"hasta":60,"creditos":32000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110403.png","nombre":"Cuerno de nieve","cantidad":5},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":8}]},{"desde":60,"hasta":70,"creditos":64000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110403.png","nombre":"Cuerno de nieve","cantidad":15},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":5}]},{"desde":70,"hasta":80,"creditos":128000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110403.png","nombre":"Cuerno de nieve","cantidad":28},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":7}]}]'::jsonb),
  ('hsr-himeko', 'honkai-star-rail', 'Himeko', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1003.png', '5', 'Fuego', 80, null, 'DPS / Sub-DPS', 'Erudición', 'Noche en la Vía Láctea', false, 'The one who repaired the Astral Express. To witness the vast starry sky, she decided to travel with the Astral Express. Her hobby is brewing hand-made coffee.

An adventurous scientist who encountered the Astral Express as a young woman when it got stranded in her homeworld. Years later, when Himeko finally repaired the Express and began her journey into the stars, she realized that this is only the beginning. On her journey to trailblaze new worlds, she would need many more companions... And while they may have different destinations, they all gaze at the same starry sky.', 'https://honkai-star-rail.fandom.com/wiki/Himeko%2FLore', 'The one who repaired the Astral Express. To witness the vast starry sky, she decided to travel with the Astral Express. Her hobby is brewing hand-made coffee.

An adventurous scientist who encountered the Astral Express as a young woman when it got stranded in her homeworld. Years later, when Himeko finally repaired the Express and began her journey into the stars, she realized that this is only the beginning. On her journey to trailblaze new worlds, she would need many more companions... And while they may have different destinations, they all gaze at the same starry sky.', 'https://honkai-star-rail.fandom.com/wiki/Himeko%2FLore', 'Una chica perdida. No recordaba cuándo se había perdido. Simplemente caminó y caminó sin parar en la noche oscura, persiguiendo el sol y la luna, una y otra vez, hasta que se cayó. Recordó cómo se veía cuando inició la universidad. Recordó su especialización elegida, la dinámica de navegación interestelar. Y ahora estaba tendida boca abajo en el barro... Miró las estrellas y, en ese momento, vio meteoros cayendo: uno, dos, tres... Y, luego, otros más pequeños que parpadeaban y destellaban muy levemente antes de que un magnífico resplandor resquebrajara el cielo nocturno. Sus extremidades la arrastraron hacia adelante, hasta donde la tierra se encontraba con el océano. En la costa, las aguas se agitaban contra ella como la marea contra un tren varado, solo y perdido. Entró y vio que el paisaje exterior empezaba a cambiar. El tren le mostró miles de mundos magníficos muy lejos, más allá de su mundo natal, pero lo suficientemente cerca como para poder llegar en tren.', 'https://honkai-star-rail.fandom.com/es/wiki/Himeko', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110402.png","nombre":"Quitina endoterma","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110402.png","nombre":"Quitina endoterma","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110402.png","nombre":"Quitina endoterma","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110402.png","nombre":"Quitina endoterma","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":9}]}]'::jsonb),
  ('hsr-himeko-nova', 'honkai-star-rail', 'Himeko Nova (Himeko • Nova)', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1510.png', '5', 'Fuego', null, null, null, 'Erudición', null, false, null, null, null, null, null, null, false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","nombre":"Crayón de la inocencia","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","nombre":"Crayón de la inocencia","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110432.png","nombre":"Protuberancia radiante","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","nombre":"Pluma creasueños","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110432.png","nombre":"Protuberancia radiante","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","nombre":"Pluma creasueños","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110432.png","nombre":"Protuberancia radiante","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","nombre":"Pincel de los sueños","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110432.png","nombre":"Protuberancia radiante","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","nombre":"Pincel de los sueños","cantidad":9}]}]'::jsonb),
  ('hsr-hook', 'honkai-star-rail', 'Hook', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1109.png', '4', 'Fuego', 80, null, 'DPS', 'Destrucción', 'Topos al rescate', false, 'Boss (self-proclaimed) of an Underworld adventure squad, The Moles. She loves freedom and sees life as a series of adventures.

Head of the adventure squad "The Moles," she calls herself Pitch-Dark Hook the Great. She doesn''t like to be called a "kid" and believes she can handle things herself without any help from adults. Adults adventure into the Fragmentum, Mr. Sampo adventures on the surface, and patients take their risky adventure seeking treatment from Natasha... Under the leadership of Hook, children can also have their own adventures!', 'https://honkai-star-rail.fandom.com/wiki/Hook%2FLore', 'Boss (self-proclaimed) of an Underworld adventure squad, The Moles. She loves freedom and sees life as a series of adventures.

Head of the adventure squad "The Moles," she calls herself Pitch-Dark Hook the Great. She doesn''t like to be called a "kid" and believes she can handle things herself without any help from adults. Adults adventure into the Fragmentum, Mr. Sampo adventures on the surface, and patients take their risky adventure seeking treatment from Natasha... Under the leadership of Hook, children can also have their own adventures!', 'https://honkai-star-rail.fandom.com/wiki/Hook%2FLore', '"██/██/██ Clima: Bueno Estado de ánimo: Muy malo".

"Hoy rompí uno de los tuvos de ensallo tubos de hensayo tubos de ensayo de la vieja bruja y me gané una buena regañina".

"¡La vieja bruja es terrible! Nunca nos deja jugar después de la comida y nos obliga a dormir la siesta. ¡La odio!".

"¡Debemos revelarnos rebelarnos contra su tiranía! ¡No podemos dejar que sesalga se salga con la suya!".

"Voy a formar un grupo llamado Los Topos, y obligaré secuestraré invitaré a todos los niños de la clínica. ¡Derrocaremos a la vieja bruja! Y luego podremos comer lo que queramos y divertirnos juntos, ¡y nadie podrá detenernos!".

"¡Y yo seré la jefa de Los Topos! ¡Y la jefa de la clínica también! Le daré a esa vieja bruja una buena regañina todos los días, y la obligaré a hacer todas las capeas tareas. ¡Mua, ja, ja!".', 'https://honkai-star-rail.fandom.com/es/wiki/Hook', false, '[{"desde":20,"hasta":30,"creditos":3200,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112011.png","nombre":"Componente antiguo","cantidad":4}]},{"desde":30,"hasta":40,"creditos":6400,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112011.png","nombre":"Componente antiguo","cantidad":8}]},{"desde":40,"hasta":50,"creditos":12800,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110402.png","nombre":"Quitina endoterma","cantidad":2},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112012.png","nombre":"Eje antiguo","cantidad":5}]},{"desde":50,"hasta":60,"creditos":32000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110402.png","nombre":"Quitina endoterma","cantidad":5},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112012.png","nombre":"Eje antiguo","cantidad":8}]},{"desde":60,"hasta":70,"creditos":64000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110402.png","nombre":"Quitina endoterma","cantidad":15},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112013.png","nombre":"Motor antiguo","cantidad":5}]},{"desde":70,"hasta":80,"creditos":128000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110402.png","nombre":"Quitina endoterma","cantidad":28},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112013.png","nombre":"Motor antiguo","cantidad":7}]}]'::jsonb),
  ('hsr-huohuo', 'honkai-star-rail', 'Huohuo', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1217.png', '5', 'Viento', 80, null, 'Support (Healer) / Buffer', 'Abundancia', 'Noche de terror', false, 'A trainee Ten-Lords Commission Judge of the Xianzhou Luofu, she is a young foxian girl possessed by a heliobus. She is a timid and weak girl who is afraid of all kinds of strange things, but is responsible for luring and subduing evil spirits.

While this foxian girl may seem fragile and weak, she is actually a judge-in-training of the Ten-Lords Commission, responsible for capturing evil. The judges sealed a heliobus named "Tail" onto her tail, making her a "Cursed One" with a tendency to attract evil beings. Despite trembling at the sight of evil spirits, she is always entrusted with the arduous task of eradicating their presence. She is well aware of her incompetence but lacks the courage to resign, so she forces herself to press on despite her fear.', 'https://honkai-star-rail.fandom.com/wiki/Huohuo%2FLore', 'A trainee Ten-Lords Commission Judge of the Xianzhou Luofu, she is a young foxian girl possessed by a heliobus. She is a timid and weak girl who is afraid of all kinds of strange things, but is responsible for luring and subduing evil spirits.

While this foxian girl may seem fragile and weak, she is actually a judge-in-training of the Ten-Lords Commission, responsible for capturing evil. The judges sealed a heliobus named "Tail" onto her tail, making her a "Cursed One" with a tendency to attract evil beings. Despite trembling at the sight of evil spirits, she is always entrusted with the arduous task of eradicating their presence. She is well aware of her incompetence but lacks the courage to resign, so she forces herself to press on despite her fear.', 'https://honkai-star-rail.fandom.com/wiki/Huohuo%2FLore', 'Cuando Huohuo despierta en la Comisión de los Diez Líderes, no se sorprende por estar ahí, sino por la atmósfera escalofriante.

Al ver su inquietud, una jueza de cabello blanco le habla con dulzura.

"Dime, pequeña, ¿cómo atravesaste el fuego?". "... Estaba al borde de la carretera, a punto de extinguirse, entonces yo... quise ayudarlo". "¿Y pusiste ese fuego en tu cola? ¿Por qué lo hiciste?". "No... No lo sé... pasó antes de que me diera cuenta... Lo siento mucho". "No te disculpes, chica de buen corazón. Sin embargo, estarás bajo custodia de ahora en adelante". "Gra-gracias, señorita". "Llámame Hanya". "Ah, gracias, Hanya. Me... me llamo Huohuo".

Los pensamientos de la jueza Hanya volvieron a unos días atrás.

La Comisión de los Diez Líderes había recibido una llamada de auxilio, y ella asumió la tarea de encontrar a la chica raposiana que estaba a punto de ser consumida por el heliobus.', 'https://honkai-star-rail.fandom.com/es/wiki/Huohuo', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110415.png","nombre":"Vestigios elevados","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110415.png","nombre":"Vestigios elevados","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110415.png","nombre":"Vestigios elevados","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110415.png","nombre":"Vestigios elevados","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":9}]}]'::jsonb),
  ('hsr-hyacine', 'honkai-star-rail', 'Hyacine', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1409.png', '4', 'Viento', 80, null, 'Debuffer / Sub-DPS', 'Memoria', 'Cono de firma de Hyacine', false, 'As the city-state in the clouds crumbles through time, the Twilight Courtyard opens its gates once more, bringing a glimmer of light to Evernight. Physician Hyacinthia is the Chrysos Heir who watches over the Coreflame of Sky. Carrying the will of her ancestors, she mends the torn fabric of dusk and dawn. May the rainbow light pour down, dissolve all grudges, and bring the dawn back to this land.', 'https://honkai-star-rail.fandom.com/wiki/Hyacine%2FLore', 'As the city-state in the clouds crumbles through time, the Twilight Courtyard opens its gates once more, bringing a glimmer of light to Evernight. Physician Hyacinthia is the Chrysos Heir who watches over the Coreflame of Sky. Carrying the will of her ancestors, she mends the torn fabric of dusk and dawn. May the rainbow light pour down, dissolve all grudges, and bring the dawn back to this land.', 'https://honkai-star-rail.fandom.com/wiki/Hyacine%2FLore', '"Extiende lentamente tus alas... Sí, como hicimos la última vez. Respira profundamente conmigo, ¿de acuerdo?". "Relájate, todo está bien... Sí, las alas se están expandiendo. Estás comiendo mucho, ¿verdad?". La luz de las velas proyectaba un cálido resplandor sobre la suave cabecita mientras la joven levantaba al caballito y lo colocaba con cuidado en la balanza.

"No te preocupes. Pronto serás tan grande y fuerte como las demás bestias aladas, ¿sí?". La joven se colocó los auriculares del estetoscopio y comenzó a realizar un examen completo. Al palpar un lado del caballito, sintió una nueva "herida" debajo de sus costillas. "¿Te lastimaste?".

Acarició con suavidad sus alas y llenó el agujero con algodón antes de sacar una aguja e hilo. "Esto va a doler un poco, pero no te preocupes, mis puntos son firmes". "Has vuelto a entrenar demasiado, ¿verdad? ¿Es porque todos te dicen que tu madre, tu abuela y todos tus antepasados son increíbles?', 'https://honkai-star-rail.fandom.com/es/wiki/Hyacine', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","nombre":"Carne pisoteada del miedo","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","nombre":"Carne pisoteada del miedo","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110425.png","nombre":"Copa de la era embriagada","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","nombre":"Pecho hendido del valor","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110425.png","nombre":"Copa de la era embriagada","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","nombre":"Pecho hendido del valor","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110425.png","nombre":"Copa de la era embriagada","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","nombre":"Torso bautizado de gloria","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110425.png","nombre":"Copa de la era embriagada","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","nombre":"Torso bautizado de gloria","cantidad":9}]}]'::jsonb),
  ('hsr-hysilens', 'honkai-star-rail', 'Hysilens', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1410.png', '4', 'Físico', 80, null, 'Debuffer', 'Nihilidad', 'Cono de firma de Hysilens', false, 'Styxia, the coastal city of intoxication and dreams, where echoes of old songs still drift among the waves. Helektra, Daughter of the Sea, Chrysos Heir who cleanses the Ocean''s Coreflame, dispels the murky undercurrents and orchestrates a banquet of revelry for the heroes beyond the sky. The show must go on. Even if hope is as fragile as bubbles, the waves will keep surging forward.', 'https://honkai-star-rail.fandom.com/wiki/Hysilens%2FLore', 'Styxia, the coastal city of intoxication and dreams, where echoes of old songs still drift among the waves. Helektra, Daughter of the Sea, Chrysos Heir who cleanses the Ocean''s Coreflame, dispels the murky undercurrents and orchestrates a banquet of revelry for the heroes beyond the sky. The show must go on. Even if hope is as fragile as bubbles, the waves will keep surging forward.', 'https://honkai-star-rail.fandom.com/wiki/Hysilens%2FLore', 'Cuando la luz del sol se filtraba a través de la superficie, la respiración del mar se volvía multicolor, siendo este el momento más alegre del día para las sirenas. ♫ Plop ♫ ♫ Pica ♫ ♫ Bum ♫ La princesa de las sirenas persigue alegremente las burbujas, adorando ese instante en que se posan brevemente sobre la punta de su nariz antes de estallar, haciendo que las ondas del agua brillen con los siete colores del arcoíris.

Las sirenas cantaban entre los vastos arrecifes de coral, y las perlas brillantes que allí se encontraban eran perfectas para adornar el arco del violín. La música fluía de los dedos de Hysirenia como una suave corriente de agua, acariciando a sus compañeras que disfrutaban plácidamente del hidromiel.

♫ "Mira, en ese barco brillante y bullicioso, qué felices deben de estar los humanos". ♫ ♫ "Aún anhelas a aquel que salvaste, mientras su voz resuena en lo profundo de tu alma". ♫ ♫ "Noble princesa, despreocupada Hysirenia, ¿a dónde irás?', 'https://honkai-star-rail.fandom.com/es/wiki/Hysilens', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","nombre":"Carne pisoteada del miedo","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","nombre":"Carne pisoteada del miedo","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","nombre":"Pecho hendido del valor","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","nombre":"Pecho hendido del valor","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","nombre":"Torso bautizado de gloria","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","nombre":"Torso bautizado de gloria","cantidad":9}]}]'::jsonb),
  ('hsr-jade', 'honkai-star-rail', 'Jade', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1314.png', '5', 'Cuántico', 80, null, 'Sub-DPS', 'Erudición', 'La esperanza es incalculable', false, 'A senior manager in the IPC Strategic Investment Department and one of the Ten Stonehearts, known for her cornerstone "Jade of Credit." A cold and elegant moneylender, she is skilled at understanding the human heart, with a personal hobby called "Bonajade Exchange." She''s willing to wait patiently for high-value acquisitions and adept at extracting value from seemingly destitute clients.

A senior manager in the IPC Strategic Investment Department and one of the Ten Stonehearts, known for her cornerstone "Jade of Credit." A beautiful and elegant moneylender, skilled in deciphering the depths of people''s minds, she often exacts a price from her adversaries and secures the IPC''s profits through collateral and contractual agreements. She is willing to go to great lengths to lay the groundwork for acquiring something of greater value, and to extract benefits from seemingly penniless clients.', 'https://honkai-star-rail.fandom.com/wiki/Jade%2FLore', 'A senior manager in the IPC Strategic Investment Department and one of the Ten Stonehearts, known for her cornerstone "Jade of Credit." A cold and elegant moneylender, she is skilled at understanding the human heart, with a personal hobby called "Bonajade Exchange." She''s willing to wait patiently for high-value acquisitions and adept at extracting value from seemingly destitute clients.

A senior manager in the IPC Strategic Investment Department and one of the Ten Stonehearts, known for her cornerstone "Jade of Credit." A beautiful and elegant moneylender, skilled in deciphering the depths of people''s minds, she often exacts a price from her adversaries and secures the IPC''s profits through collateral and contractual agreements. She is willing to go to great lengths to lay the groundwork for acquiring something of greater value, and to extract benefits from seemingly penniless clients.', 'https://honkai-star-rail.fandom.com/wiki/Jade%2FLore', 'A la galaxia Cadena de Plata se acercaba una tormenta de iones, de esas que tienen lugar una vez cada cien Eras del Ámbar. Una joven de una familia que se dedicaba al comercio de joyas estaba en la terraza, contemplando un cielo inundado de colores inusuales.

 "Es hora de irse, señorita. El Sr. Horus alquiló una nave estelar entera, y debemos dirigirnos al puerto estelar de Basvia para refugiarnos". "Pero los plebeyos de la Cadena de Plata no saben de la tormenta, ¿no?". "No tenemos opción. Es para prevenir posibles disturbios". "... Vete si quieres, pero yo me quedaré aquí y buscaré la ayuda de esa mujer". "Pero esta tormenta de iones borrará toda tu riqueza...". "Siempre hay cosas que no se pueden medir simplemente por su valor, como... la bondad y la vida". El anciano mayordomo dejó escapar un profundo suspiro.

La joven entró en la casa de empeños. "Bienvenida a la Casa de Empeño Bonajade. ¿Quién eres? ¿Y qué buscas?".', 'https://honkai-star-rail.fandom.com/es/wiki/Jade', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","nombre":"Componente del acumulador de sueños","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","nombre":"Componente del acumulador de sueños","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110426.png","nombre":"Soplete de ensueño","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","nombre":"Válvula del flujo de sueños","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110426.png","nombre":"Soplete de ensueño","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","nombre":"Válvula del flujo de sueños","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110426.png","nombre":"Soplete de ensueño","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","nombre":"Motor creasueños","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110426.png","nombre":"Soplete de ensueño","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","nombre":"Motor creasueños","cantidad":9}]}]'::jsonb),
  ('hsr-jiaoqiu', 'honkai-star-rail', 'Jiaoqiu', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1218.png', '5', 'Fuego', 80, null, 'Debuffer / Sub-DPS', 'Nihilidad', 'Incontables primaveras', false, 'A foxian healer and counselor from the Xianzhou Yaoqing. Often greets people with a smile on his face and a scheme in his heart. Born into a prestigious Alchemy Commission family, he once withdrew from practicing medicine due to a broken heart. However, he returned to the field to treat "the Merlin''s Claw," General Feixiao. Skilled in the study of alchemical prescription that views food as medicine, especially those that induce a sensation of spiciness. He invented a cauldron-based medicinal formula known as the "nine-squared grid.""', 'https://honkai-star-rail.fandom.com/wiki/Jiaoqiu%2FLore', 'A foxian healer and counselor from the Xianzhou Yaoqing. Often greets people with a smile on his face and a scheme in his heart. Born into a prestigious Alchemy Commission family, he once withdrew from practicing medicine due to a broken heart. However, he returned to the field to treat "the Merlin''s Claw," General Feixiao. Skilled in the study of alchemical prescription that views food as medicine, especially those that induce a sensation of spiciness. He invented a cauldron-based medicinal formula known as the "nine-squared grid.""', 'https://honkai-star-rail.fandom.com/wiki/Jiaoqiu%2FLore', 'El Lago Vendaval, el Yaoqing. En la lluvia neblinosa, el follaje y las flores de falso nenúfar amarillo decoraban el lago mientras los peces juguetones saltaban fuera del agua de vez en cuando. En el borde de este lago abundan flores de loto y castañas de agua, y las tortugas muy viejas tomando el sol en la playa de guijarros dibujan una escena cotidiana.

Un joven raposiano que llevaba a la espalda una canasta para guardar los ingredientes que recolectaba remaba en un pequeño bote. Las gotas de lluvia le caían por las orejas antes de que se las quitara con suavidad. Mientras recogía las plantas de corazón flotantes y las flores de loto, pelaba los tallos de arroz silvestre y los lanzaba a su boca con indiferencia. "Qué dulce y refrescante, deleita mi paladar...". Después de recoger las plantas, dirigió el bote a la orilla y cruzó el borde del lago con gran facilidad antes de cambiarse a un atuendo de sanador. ...', 'https://honkai-star-rail.fandom.com/es/wiki/Jiaoqiu', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":9}]}]'::jsonb),
  ('hsr-jing-yuan', 'honkai-star-rail', 'Jing Yuan', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1204.png', '5', 'Rayo', 80, null, 'DPS', 'Erudición', 'Antes del amanecer', false, 'The Divine Foresight, one of the Seven Arbiter-Generals of the Xianzhou Alliance, leads the Cloud Knights of the Xianzhou Luofu. A student of the Luofu''s previous Sword Champion, though not known for his martial prowess.

The Divine Foresight, one of the Seven Arbiter-Generals. Although his appearance may be one of indolence, he is more meticulous than seemingly meets the eye. He does not consider saving a situation from the brink of disaster to be a show of wisdom, and is thus fastidious with routine affairs to avoid any potential problems. Due to his careful management, Xianzhou has enjoyed many years of peace, with Jing Yuan''s seemingly lazy demeanor having earned him the moniker of the "Dozing General."', 'https://honkai-star-rail.fandom.com/wiki/Jing%20Yuan%2FLore', 'The Divine Foresight, one of the Seven Arbiter-Generals of the Xianzhou Alliance, leads the Cloud Knights of the Xianzhou Luofu. A student of the Luofu''s previous Sword Champion, though not known for his martial prowess.

The Divine Foresight, one of the Seven Arbiter-Generals. Although his appearance may be one of indolence, he is more meticulous than seemingly meets the eye. He does not consider saving a situation from the brink of disaster to be a show of wisdom, and is thus fastidious with routine affairs to avoid any potential problems. Due to his careful management, Xianzhou has enjoyed many years of peace, with Jing Yuan''s seemingly lazy demeanor having earned him the moniker of the "Dozing General."', 'https://honkai-star-rail.fandom.com/wiki/Jing%20Yuan%2FLore', '"Gran Adivina, ¿por qué usamos un tablero cuadrado, pero piezas redondas para el ajedrez estelar?". "¿Es por el cielo redondo? Las antiguas civilizaciones creían que la tierra era plana. El juego se inspira en los viejos tiempos y la conquista imperial, así que es cuadrado. Y las piezas... La gente creía que el cielo era una cúpula redonda, y las piezas giraban como las estrellas. Los de abajo también eran redondos". "No, no". "Ya predije tus próximos cuarenta y ocho movimientos. Jing Yuan, si quieres distraerme con preguntas, te sugiero que abandones mientras llevas la delantera". "Ah, ¿cómo puedes sospechar que tengo esa intención?". "No interrumpas. Continúa hablando". "Es cierto que el ajedrez es una metáfora y describe la condición humana. Las reglas de la guerra están claramente establecidas, con las acciones de cada bando: avanzar, retirarse, saltar... Avanzar o retroceder, por aquí o por allá. Por eso el tablero es cuadrado.', 'https://honkai-star-rail.fandom.com/es/wiki/Jing%20Yuan', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110414.png","nombre":"Báculo del Cambiaformas","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110414.png","nombre":"Báculo del Cambiaformas","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110414.png","nombre":"Báculo del Cambiaformas","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110414.png","nombre":"Báculo del Cambiaformas","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":9}]}]'::jsonb),
  ('hsr-jingliu', 'honkai-star-rail', 'Jingliu', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1212.png', '5', 'Hielo', 80, null, 'DPS', 'Destrucción', 'Yo seré mi propia espada', false, 'Former Sword Champion of the Luofu, and the creator of the Cloud Knights'' legends of undefeated might. Now, her name has been wiped from the records, and she is a traitor of the Xianzhou walking on the fine line between sanity and mara-struck.

Former Sword Champion of the Luofu, and the reason behind the Cloud Knights'' mythical reputation of implacable might. Now, her name has been wiped from the records, and she is a traitor of the Xianzhou walking on the fine line between sanity and mara-struck.', 'https://honkai-star-rail.fandom.com/wiki/Jingliu%2FLore', 'Former Sword Champion of the Luofu, and the creator of the Cloud Knights'' legends of undefeated might. Now, her name has been wiped from the records, and she is a traitor of the Xianzhou walking on the fine line between sanity and mara-struck.

Former Sword Champion of the Luofu, and the reason behind the Cloud Knights'' mythical reputation of implacable might. Now, her name has been wiped from the records, and she is a traitor of the Xianzhou walking on the fine line between sanity and mara-struck.', 'https://honkai-star-rail.fandom.com/wiki/Jingliu%2FLore', 'Una espada de más de un metro de largo que no pesa nada. No está forjada de hierro ordinario, sino condensada a partir de un eje de hielo afilado. Brilla con una luz tenue, como si fuera un rayo de luz de luna en la mano de quien la blande.

"Una espada de más de un metro de largo que pesa unos 3 kilos. Sostenla en la mano y atraviesa al enemigo con el extremo afilado". La mujer con uniforme militar mueve ligeramente la mano. Como si estuviera viva, la espada salta del estante para armas y se desenvaina tan pronto como aterriza en la palma de la mujer. La hoja se clava en el suelo junto a los pies de la chica y se queda vibrando con un zumbido estridente. "¿Lo has aprendido? Si es así, ve a luchar contra las bestias de guerra más comunes que los borisin usan en sus fuerzas terrestres. Una vez que hayas matado a 10 guivernos, daré por terminada tu primera lección". Ella permanece en silencio y mira a su alrededor.', 'https://honkai-star-rail.fandom.com/es/wiki/Jingliu', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110413.png","nombre":"Quitina gélida","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110413.png","nombre":"Quitina gélida","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110413.png","nombre":"Quitina gélida","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110413.png","nombre":"Quitina gélida","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":9}]}]'::jsonb),
  ('hsr-kafka', 'honkai-star-rail', 'Kafka', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1005.png', '5', 'Rayo', 80, null, 'DPS (DoT)', 'Nihilidad', 'Solo hay que tener paciencia', false, 'A member of the Stellaron Hunters. A dashing, collected, and professional beauty. Used the enchantment of Spirit Whisper to set up (Trailblazer) to absorb the Stellaron. Her hobby is shopping for and organizing her collection of coats.

On the Interastral Peace Corporation''s wanted list, Kafka''s record only shows her name and a note about her "interest in collecting coats." Little is known about this Stellaron Hunter aside from her being one of "Destiny''s Slave" Elio''s most trusted members. In order to achieve Elio''s envisioned future, Kafka gets to work.', 'https://honkai-star-rail.fandom.com/wiki/Kafka%2FLore', 'A member of the Stellaron Hunters. A dashing, collected, and professional beauty. Used the enchantment of Spirit Whisper to set up (Trailblazer) to absorb the Stellaron. Her hobby is shopping for and organizing her collection of coats.

On the Interastral Peace Corporation''s wanted list, Kafka''s record only shows her name and a note about her "interest in collecting coats." Little is known about this Stellaron Hunter aside from her being one of "Destiny''s Slave" Elio''s most trusted members. In order to achieve Elio''s envisioned future, Kafka gets to work.', 'https://honkai-star-rail.fandom.com/wiki/Kafka%2FLore', '"Kafka, mujer humana oriunda de Pteruges-V: Nueva Babilonia. Miembro principal de los Cazadores de Estelaron, segunda al mando del Esclavo del Destino. Culpable de los siguientes delitos: invasión de Pier Point, dos cargos; robo en Pier Point; desaparición del sistema estelar Trovys; los incidentes relacionados con el Estelaron de Jemorse, Bayjhana, Shilla-39C, Ulmora, 7-Midville, Loar-51 y Dro''a; ciberataques contra Pier Point, cuatro cargos; ciberataques contra el planeta Tornillia; ciberataques contra la Estación Espacial Herta; la rebelión de Jepella. Se sospecha que está relacionada con las siguientes infracciones: los incidentes relacionados con el Estelaron de Sich-Lala, Inupeis, Oun-G7, Zukov, Lidovia, Illily, Attouine y Buhayama. Nivel de búsqueda: el más alto. Viva o muerta". Orden de captura de la Corporación para la Paz Interastral.', 'https://honkai-star-rail.fandom.com/es/wiki/Kafka', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","nombre":"Instinto del ladrón","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","nombre":"Instinto del ladrón","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110414.png","nombre":"Báculo del Cambiaformas","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","nombre":"Ambición distorsionada","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110414.png","nombre":"Báculo del Cambiaformas","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","nombre":"Ambición distorsionada","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110414.png","nombre":"Báculo del Cambiaformas","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","nombre":"Voluntad de conquista","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110414.png","nombre":"Báculo del Cambiaformas","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","nombre":"Voluntad de conquista","cantidad":9}]}]'::jsonb),
  ('hsr-the-dahlia', 'honkai-star-rail', 'La Dalia (The Dahlia)', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1321.png', '5', 'Fuego', null, null, null, 'Nihilidad', null, false, null, null, null, null, null, null, false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","nombre":"Jirones de pensamientos","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","nombre":"Jirones de pensamientos","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110432.png","nombre":"Protuberancia radiante","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","nombre":"Fragmento de impresiones","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110432.png","nombre":"Protuberancia radiante","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","nombre":"Fragmento de impresiones","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110432.png","nombre":"Protuberancia radiante","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","nombre":"Fragmento de deseos","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110432.png","nombre":"Protuberancia radiante","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","nombre":"Fragmento de deseos","cantidad":9}]}]'::jsonb),
  ('hsr-lingsha', 'honkai-star-rail', 'Lingsha', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1222.png', '5', 'Fuego', 80, null, 'Support (Healer) / Sub-DPS', 'Abundancia', 'El aroma perdura', false, 'The new Cauldron Master of the Xianzhou Luofu''s Alchemy Commission is one perceptive and intelligent Vidyadhara healer. With a keen sense of smell, she diagnoses ailments and calms minds with aromatic therapy. Adept at navigating complex social relationships, she can remain impeccably composed even when turmoil rages within.', 'https://honkai-star-rail.fandom.com/wiki/Lingsha%2FLore', 'The new Cauldron Master of the Xianzhou Luofu''s Alchemy Commission is one perceptive and intelligent Vidyadhara healer. With a keen sense of smell, she diagnoses ailments and calms minds with aromatic therapy. Adept at navigating complex social relationships, she can remain impeccably composed even when turmoil rages within.', 'https://honkai-star-rail.fandom.com/wiki/Lingsha%2FLore', 'A medida que nubes de humo negro rodean el caldero, la joven se sienta expectante en el cojín, mirando fijamente el traqueteo de la tapa con sus brillantes ojos. Tras una explosión que resonó en todo el cuarto, la joven corre con entusiasmo al consultorio de la maestra sujetando una píldora cristalina, a pesar de que todo su cuerpo luce como un pergamino quemado que dejaron muy cerca de una vela. "¡Maestra Yunhua! Mire, ¡lo logré!".

La líder Yunhua está atendiendo pacientes en un consultorio abarrotado. Al ver a su maestra enfocada y concentrada, la joven se esconde detrás de su maestra obedientemente y baja su cabeza para oler el aroma de la píldora medicinal. "Este pulso... es uno difícil...". La joven escucha la sospecha de su maestra y se acerca al paciente para oler. "Pequeña Dan Zhu, ¡tu sentido del olfato es insuperable! ¿Me podrías decir algo sobre la condición de este paciente?". Yunhua le indica a la joven que avance y la mira de manera alentadora. "Humm...', 'https://honkai-star-rail.fandom.com/es/wiki/Lingsha', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","nombre":"Brote verde inmortal","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","nombre":"Flor etérea inmortal","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110422.png","nombre":"Corazón ardiente","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","nombre":"Rama gloriosa inmortal","cantidad":9}]}]'::jsonb),
  ('hsr-luka', 'honkai-star-rail', 'Luka', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1111.png', '4', 'Físico', 80, null, 'Sub-DPS / Debuffer', 'Nihilidad', 'Determinación', false, 'The boxing champion in Belobog''s Underworld, and one of Wildfire''s most capable fighters. The consecutive reigning champion of the Fight Club, whose enthusiasm inspires children of the Underworld to dream big.

An optimistic and carefree fighter with a mechanical arm. Skilled in mixed martial arts and is a Wildfire member. From the fight cage to the battlefield, and from a fighter to a warrior, Luka uses his strength to protect the people of the Underworld. He wishes to bring hope to others precisely because he had experienced despair himself.', 'https://honkai-star-rail.fandom.com/wiki/Luka%2FLore', 'The boxing champion in Belobog''s Underworld, and one of Wildfire''s most capable fighters. The consecutive reigning champion of the Fight Club, whose enthusiasm inspires children of the Underworld to dream big.

An optimistic and carefree fighter with a mechanical arm. Skilled in mixed martial arts and is a Wildfire member. From the fight cage to the battlefield, and from a fighter to a warrior, Luka uses his strength to protect the people of the Underworld. He wishes to bring hope to others precisely because he had experienced despair himself.', 'https://honkai-star-rail.fandom.com/wiki/Luka%2FLore', 'Levanta el martillo de acero una y otra vez.

Las chispas estallan ante sus ojos y el sonido del metal ahoga el ruido sordo de los músculos y articulaciones. El joven todavía no es lo suficientemente alto como para alcanzar las herramientas situadas sobre el armario de hierro, pero la fuerza con la que blande el martillo de acero se asemeja a la de los artesanos más hábiles.

Esta tienda es su vida. Su padre se sienta frente a la entrada y limpia una y otra vez el oxidado letrero de la puerta. De vez en cuando, se tumba sobre su cama dura e imagina su futuro, pero no importa a dónde lo lleve su mente, la figura de su padre siempre aparece en el fondo de sus pensamientos.

De pronto, se oyen pasos acercándose. Por un momento deja a un lado su trabajo. Su padre se pone de pie, con su figura robusta, pero ligeramente encorvada. Son los miembros de Llamarada otra vez.', 'https://honkai-star-rail.fandom.com/es/wiki/Luka', false, '[{"desde":20,"hasta":30,"creditos":3200,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112011.png","nombre":"Componente antiguo","cantidad":4}]},{"desde":30,"hasta":40,"creditos":6400,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112011.png","nombre":"Componente antiguo","cantidad":8}]},{"desde":40,"hasta":50,"creditos":12800,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110401.png","nombre":"Dientes rotos del huargo férreo","cantidad":2},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112012.png","nombre":"Eje antiguo","cantidad":5}]},{"desde":50,"hasta":60,"creditos":32000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110401.png","nombre":"Dientes rotos del huargo férreo","cantidad":5},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112012.png","nombre":"Eje antiguo","cantidad":8}]},{"desde":60,"hasta":70,"creditos":64000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110401.png","nombre":"Dientes rotos del huargo férreo","cantidad":15},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112013.png","nombre":"Motor antiguo","cantidad":5}]},{"desde":70,"hasta":80,"creditos":128000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110401.png","nombre":"Dientes rotos del huargo férreo","cantidad":28},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112013.png","nombre":"Motor antiguo","cantidad":7}]}]'::jsonb),
  ('hsr-luocha', 'honkai-star-rail', 'Luocha', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1203.png', '5', 'Imaginario', 80, null, 'Support (Healer)', 'Abundancia', 'Ecos del ataúd', false, 'Carrying a coffin wherever he goes, he is a foreign trader who came from beyond the stellar seas. Has excellent medical skills.

An elegant and handsome blond young man who carries a giant coffin on his back. As an intergalactic merchant, he was unfortunately caught in the Xianzhou Luofu''s Stellaron crisis. And that is how he found his mastery of medicine to come in handy.', 'https://honkai-star-rail.fandom.com/wiki/Luocha%2FLore', 'Carrying a coffin wherever he goes, he is a foreign trader who came from beyond the stellar seas. Has excellent medical skills.

An elegant and handsome blond young man who carries a giant coffin on his back. As an intergalactic merchant, he was unfortunately caught in the Xianzhou Luofu''s Stellaron crisis. And that is how he found his mastery of medicine to come in handy.', 'https://honkai-star-rail.fandom.com/wiki/Luocha%2FLore', '"¿Y usted es...?".
"Un comerciante ambulante".
"¿Cuál es el propósito de su visita?".
"Negocios".
"¿Jura no violar las leyes y normas de la Alianza Xianzhou, llevar a cabo actividades comerciales de acuerdo con la ley y no realizar ninguna actividad fuera del alcance de su visado?".
"Sí, lo juro".
"¿Jura no realizar ninguna investigación ilegal relacionada con la longevidad?".
"Eh... Sí, lo juro".
"Estupendo, firme aquí".

"Sr. Luocha, bienvenido al Luofu de Xianzhou".', 'https://honkai-star-rail.fandom.com/es/wiki/Luocha', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110407.png","nombre":"Corona dorada de la sombra del pasado","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110407.png","nombre":"Corona dorada de la sombra del pasado","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110407.png","nombre":"Corona dorada de la sombra del pasado","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110407.png","nombre":"Corona dorada de la sombra del pasado","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":9}]}]'::jsonb),
  ('hsr-lynx', 'honkai-star-rail', 'Lynx', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1110.png', '4', 'Cuántico', 80, null, 'Support (Healer)', 'Abundancia', 'Momento de calidez', false, 'A Belobogian Snow Plains Explorer, and the youngest of the Landau siblings. Calm and collected, with a strong drive for action. Often embarks on solo adventures to explore the snowy wilderness.

The youngest daughter of the Landau family, and one of Belobog''s best extreme environments explorers. She is highly capable of action despite her apparent lack of motivation. She only appears introverted and lazy to avoid unnecessary socialization. As for what counts as unnecessary socialization — "Um, aren''t all socialization unnecessary?"', 'https://honkai-star-rail.fandom.com/wiki/Lynx%2FLore', 'A Belobogian Snow Plains Explorer, and the youngest of the Landau siblings. Calm and collected, with a strong drive for action. Often embarks on solo adventures to explore the snowy wilderness.

The youngest daughter of the Landau family, and one of Belobog''s best extreme environments explorers. She is highly capable of action despite her apparent lack of motivation. She only appears introverted and lazy to avoid unnecessary socialization. As for what counts as unnecessary socialization — "Um, aren''t all socialization unnecessary?"', 'https://honkai-star-rail.fandom.com/wiki/Lynx%2FLore', 'Los paisajes de las llanuras nevadas están demasiado lejos de la vida cotidiana de Belobog, tan lejos que la niña solo puede verlos en sus sueños.

En la escuela, había leído en los libros de historia lo vasto y colorido que era el mundo antes del Hielo Eterno. Sin embargo, cuando Lynx preguntaba más detalles a su profesor, este siempre respondía decepcionado: "Por desgracia, esto solo se encuentra en las profundidades de las llanuras nevadas...".

En la clase de geografía, a menudo oía al profesor hablar sobre un extraño fenómeno celeste conocido como "aurora boreal" e imaginaba aquella luz brillante por todo el cielo.', 'https://honkai-star-rail.fandom.com/es/wiki/Lynx', false, '[{"desde":20,"hasta":30,"creditos":3200,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":4}]},{"desde":30,"hasta":40,"creditos":6400,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":8}]},{"desde":40,"hasta":50,"creditos":12800,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110416.png","nombre":"Clavo del simio","cantidad":2},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":5}]},{"desde":50,"hasta":60,"creditos":32000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110416.png","nombre":"Clavo del simio","cantidad":5},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":8}]},{"desde":60,"hasta":70,"creditos":64000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110416.png","nombre":"Clavo del simio","cantidad":15},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":5}]},{"desde":70,"hasta":80,"creditos":128000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110416.png","nombre":"Clavo del simio","cantidad":28},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":7}]}]'::jsonb),
  ('hsr-march-7th', 'honkai-star-rail', 'March 7th', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1001.png', '4', 'Hielo', 80, null, 'Tanque / Debuffer', 'Conservación', 'El primer día del resto de mi vida', false, 'A girl who once slumbered in eternal ice and knows nothing about her past. To find out the truth about her origins, she decided to travel with the Astral Express. As of right now, she has prepared about 67 different versions of her life story for herself.

March 7th in a Xianzhou-styled outfit. A sword-wielding female martial artist. Learning swordplay from both Yunli and Yanqing, she is eager to create more beautiful memories on the Xianzhou.

A spirited and quirky young girl who is into all the things girls her age are interested in, such as taking photos. She was awakened from a piece of drifting eternal ice, only to find that she knows nothing about herself or her past. Though initially feeling dejected, she decided to name herself after the date of her rebirth. And thus, on that day, March 7th was born.', 'https://honkai-star-rail.fandom.com/wiki/March%207th%2FLore', 'A girl who once slumbered in eternal ice and knows nothing about her past. To find out the truth about her origins, she decided to travel with the Astral Express. As of right now, she has prepared about 67 different versions of her life story for herself.

March 7th in a Xianzhou-styled outfit. A sword-wielding female martial artist. Learning swordplay from both Yunli and Yanqing, she is eager to create more beautiful memories on the Xianzhou.

A spirited and quirky young girl who is into all the things girls her age are interested in, such as taking photos. She was awakened from a piece of drifting eternal ice, only to find that she knows nothing about herself or her past. Though initially feeling dejected, she decided to name herself after the date of her rebirth. And thus, on that day, March 7th was born.', 'https://honkai-star-rail.fandom.com/wiki/March%207th%2FLore', '¿Por qué le gusta tomar fotos a Siete de Marzo? "Primero, a una chica como yo debería gustarle tomar fotos". "Segundo, nunca olvidas aquello que fotografiaste".

¿Qué sabe Siete de Marzo de fotografía? "Primero, cuando tomes fotos de platos de comida rara, todos los detalles deben poder verse en la foto porque «tomar fotos de comida equivale a comérsela. Cada detalle importa»". "Segundo, si tomas fotos con los ojos cerrados, capturarás la expresión de otro con sus ojos cerrados".

¿Por qué Siete de Marzo siempre lleva su cámara? "La próxima vez que alguien intente congelarme, ¡por lo menos tendré mi cámara!".

¿Y por qué no toma Siete de Marzo fotos directamente con su teléfono? "Ah, sí, por qué no... ¡espera, es porque me gustan las cámaras!".', 'https://honkai-star-rail.fandom.com/es/wiki/Siete%20de%20Marzo', false, '[{"desde":20,"hasta":30,"creditos":3200,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","nombre":"Instinto del ladrón","cantidad":4}]},{"desde":30,"hasta":40,"creditos":6400,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","nombre":"Instinto del ladrón","cantidad":8}]},{"desde":40,"hasta":50,"creditos":12800,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110403.png","nombre":"Cuerno de nieve","cantidad":2},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","nombre":"Ambición distorsionada","cantidad":5}]},{"desde":50,"hasta":60,"creditos":32000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110403.png","nombre":"Cuerno de nieve","cantidad":5},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","nombre":"Ambición distorsionada","cantidad":8}]},{"desde":60,"hasta":70,"creditos":64000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110403.png","nombre":"Cuerno de nieve","cantidad":15},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","nombre":"Voluntad de conquista","cantidad":5}]},{"desde":70,"hasta":80,"creditos":128000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110403.png","nombre":"Cuerno de nieve","cantidad":28},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","nombre":"Voluntad de conquista","cantidad":7}]}]'::jsonb),
