  ('hsr-tribbie', 'honkai-star-rail', 'Tribbie', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1403.png', '5', 'Cuántico', 80, null, 'Buffer', 'Armonía', 'Cono de firma de Tribbie', false, 'From that holy land blessed by the tripartite prophecy, the messenger split into a thousand forms, embarking on a long journey. Tribios, Holy Maiden of Janusopolis, the Chrysos Heir who stole Passage''s Coreflame, toiled for the masses and brought the news of deliverance to all domains. —Seek the children of humanity with golden blood in their veins, shatter the dimmest dark in this world, and walk toward the tomorrow where the stars gleam.', 'https://honkai-star-rail.fandom.com/wiki/Tribbie%2FLore', 'From that holy land blessed by the tripartite prophecy, the messenger split into a thousand forms, embarking on a long journey. Tribios, Holy Maiden of Janusopolis, the Chrysos Heir who stole Passage''s Coreflame, toiled for the masses and brought the news of deliverance to all domains. —Seek the children of humanity with golden blood in their veins, shatter the dimmest dark in this world, and walk toward the tomorrow where the stars gleam.', 'https://honkai-star-rail.fandom.com/wiki/Tribbie%2FLore', 'Desde aquella tierra sagrada bendecida por la profecía tripartita, la mensajera se dividió en mil formas y emprendió un largo viaje. Tribios, Santa Doncella de Janusópolis y Heredera de Crisos que robó la Llama Central del Tránsito, se afanó por los suyos y llevó la noticia de la salvación a todos los dominios. "Buscad a los hijos de la humanidad con sangre dorada en las venas, romped la más densa oscuridad de este mundo y caminad hacia el mañana en el que brillan las estrellas".', 'https://honkai-star-rail.fandom.com/wiki/Tribbie%2FLore', true, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","nombre":"Carne pisoteada del miedo","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","nombre":"Carne pisoteada del miedo","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","nombre":"Pecho hendido del valor","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","nombre":"Pecho hendido del valor","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","nombre":"Torso bautizado de gloria","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110436.png","nombre":"Claro de luna velado","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","nombre":"Torso bautizado de gloria","cantidad":9}]}]'::jsonb),
  ('hsr-welt', 'honkai-star-rail', 'Welt', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1004.png', '5', 'Imaginario', 80, null, 'Debuffer / Sub-DPS', 'Nihilidad', 'En el nombre del mundo', false, 'A seasoned member of the Express crew. The passion buried in his heart burns anew as he enjoys this fresh adventure. Occasionally, he would sketch the experiences in a notebook.

The wise and sophisticated former Anti-Entropy Sovereign who inherits the name of the world — Welt. He has saved Earth from annihilation time and time again. After the incident with St. Fountain came to a close, Welt had no choice but to venture with the initiator of the incident to the other side of the portal. Perhaps even he didn''t expect the new journey nor companions that awaited him there.', 'https://honkai-star-rail.fandom.com/wiki/Welt%2FLore', 'A seasoned member of the Express crew. The passion buried in his heart burns anew as he enjoys this fresh adventure. Occasionally, he would sketch the experiences in a notebook.

The wise and sophisticated former Anti-Entropy Sovereign who inherits the name of the world — Welt. He has saved Earth from annihilation time and time again. After the incident with St. Fountain came to a close, Welt had no choice but to venture with the initiator of the incident to the other side of the portal. Perhaps even he didn''t expect the new journey nor companions that awaited him there.', 'https://honkai-star-rail.fandom.com/wiki/Welt%2FLore', 'De camino al portal, Welt sacó un lápiz y comenzó a delinear un boceto. En los últimos ocho años, había estado repitiendo esta tarea. Antes de eso, construía objetos de una manera diferente, siempre que pudiera hacerse una imagen mental. Sin embargo, nunca consideró esto como una "creación", porque eran solo objetos originales que aparecían en el mundo y que no tenían nada que ver con su mente. Esta es la responsabilidad diaria de Welt, quien heredó el nombre del mundo. Si hay que rescatar al mundo, se convertirá en ese héroe sin dudarlo. Ya cayó muchas veces y fue objeto de burlas muchas más, pero siempre estará frente a todos, desde el pasado hasta el futuro, y nunca cambiará. Solo que ahora se ha embarcado en un nuevo viaje.', 'https://honkai-star-rail.fandom.com/es/wiki/Welt', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","nombre":"Pin del guardia","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","nombre":"Pin del guardia","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110407.png","nombre":"Corona dorada de la sombra del pasado","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","nombre":"Insignia del guardia","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110407.png","nombre":"Corona dorada de la sombra del pasado","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","nombre":"Insignia del guardia","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110407.png","nombre":"Corona dorada de la sombra del pasado","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","nombre":"Medalla del guardia","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110407.png","nombre":"Corona dorada de la sombra del pasado","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","nombre":"Medalla del guardia","cantidad":9}]}]'::jsonb),
  ('hsr-xueyi', 'honkai-star-rail', 'Xueyi', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1214.png', '4', 'Cuántico', 80, null, 'DPS', 'Destrucción', 'Promesa imborrable / Sobre la caída', false, 'Judge of the Ten-Lords Commission, which presides over the jurisdiction of life and death on the Luofu. For years after her death, she inhabited a puppet body and returned to the world to fulfill her mission.

One of the judges of the Ten-Lords Commission on the Luofu. She is in charge of "detention" among the four judges of detention, interrogation, incarceration, and punishment. With iron chain and Mara-Sunder Awl in hand in tireless pursuit of recidivists, she will forthwith ensnare and subdue them all. The mortal coil of her past being has been reduced to ashes. She is reanimated via a puppet body. For each villain she captures, she gets in return half a day in the world of the living.', 'https://honkai-star-rail.fandom.com/wiki/Xueyi%2FLore', 'Judge of the Ten-Lords Commission, which presides over the jurisdiction of life and death on the Luofu. For years after her death, she inhabited a puppet body and returned to the world to fulfill her mission.

One of the judges of the Ten-Lords Commission on the Luofu. She is in charge of "detention" among the four judges of detention, interrogation, incarceration, and punishment. With iron chain and Mara-Sunder Awl in hand in tireless pursuit of recidivists, she will forthwith ensnare and subdue them all. The mortal coil of her past being has been reduced to ashes. She is reanimated via a puppet body. For each villain she captures, she gets in return half a day in the world of the living.', 'https://honkai-star-rail.fandom.com/wiki/Xueyi%2FLore', '"Veredicto de redención kármica de los Diez Líderes".

Vestida de blanco nieve, la jueza salió de la calle en penumbra, lo que oscureció su huida final.

El hombre se acercó, pero el estridente temblor en su voz delataba su miedo: "¿Cómo que... no es suficiente atraparlos?".

Puede que haya comenzado con un "Cómo", pero no como una pregunta abierta, sino más bien como una pregunta retórica. El análisis semántico va y viene en la mente, y no hay otra información más que "el objetivo sabía claramente con quién había complicidad".

Ella decidió ejecutar la misión que se le había asignado de inmediato.

Los globos oculares, la frente, la barbilla, el corazón, el extracto glandular, la parte inferior del abdomen... Con una mirada, marcó todas las partes que podrían servir para un único golpe efectivo. A pesar de que los raposianos eran conocidos por sus reacciones rápidas, su oponente había quedado completamente expuesto, y una ronda...', 'https://honkai-star-rail.fandom.com/es/wiki/Xueyi', false, '[{"desde":20,"hasta":30,"creditos":3200,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":4}]},{"desde":30,"hasta":40,"creditos":6400,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","nombre":"Núcleo apagado","cantidad":8}]},{"desde":40,"hasta":50,"creditos":12800,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110416.png","nombre":"Clavo del simio","cantidad":2},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":5}]},{"desde":50,"hasta":60,"creditos":32000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110416.png","nombre":"Clavo del simio","cantidad":5},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","nombre":"Núcleo reluciente","cantidad":8}]},{"desde":60,"hasta":70,"creditos":64000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110416.png","nombre":"Clavo del simio","cantidad":15},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":5}]},{"desde":70,"hasta":80,"creditos":128000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110416.png","nombre":"Clavo del simio","cantidad":28},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","nombre":"Núcleo serpenteante","cantidad":7}]}]'::jsonb),
  ('hsr-yanqing', 'honkai-star-rail', 'Yanqing', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1209.png', '5', 'Hielo', 80, null, 'DPS', 'Cacería', 'Dormir como un tronco', false, 'General Jing Yuan''s retainer. A gifted swordsman who hasn''t even come of age. No one can best Yanqing when he holds a sword in hand.

The spirited lieutenant of the Xianzhou Luofu, and also its most proficient swordsman. He was born for the sword and is obsessed with it. Whenever a sword rests in Yanqing''s hand, none would dare underestimate this genius still in the early days of his youth. Perhaps the only thing capable of dulling his treasured blade''s sharp edge is time.', 'https://honkai-star-rail.fandom.com/wiki/Yanqing%2FLore', 'General Jing Yuan''s retainer. A gifted swordsman who hasn''t even come of age. No one can best Yanqing when he holds a sword in hand.

The spirited lieutenant of the Xianzhou Luofu, and also its most proficient swordsman. He was born for the sword and is obsessed with it. Whenever a sword rests in Yanqing''s hand, none would dare underestimate this genius still in the early days of his youth. Perhaps the only thing capable of dulling his treasured blade''s sharp edge is time.', 'https://honkai-star-rail.fandom.com/wiki/Yanqing%2FLore', 'El teniente más joven en la historia de los Nimbocaballeros, guardaespaldas del general Jing Yuan y coleccionista de espadas de la Comisión de Artesanía... Con todos estos títulos y los rumores en torno a este niño prodigio, es increíble que solo sea un niño.

Desde que tenía uso de razón, Yanqing sigue a Jing Yuan como una sombra y ayuda a la Sede de la Premonición Divina a resolver sus problemas. A cambio, Jing Yuan le enseñó técnicas de espada y el arte de la guerra. Después de años de entrenamiento, la sabiduría de Yanqing es tan ágil e ingeniosa como su impecable espada.

Según la Doctrina marcial de los Nimbocaballeros, bloquear seis espadas voladoras al mismo tiempo es algo que el jefe instructor de los Nimbocaballeros no pudo dominar ni después de entrenar durante un siglo. La frase que todas las personas de Xianzhou usan para describir el talento en combate de Yanqing es: "Un espadachín dotado que nació para luchar".', 'https://honkai-star-rail.fandom.com/es/wiki/Yanqing', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","nombre":"Instinto del ladrón","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","nombre":"Instinto del ladrón","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110413.png","nombre":"Quitina gélida","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","nombre":"Ambición distorsionada","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110413.png","nombre":"Quitina gélida","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","nombre":"Ambición distorsionada","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110413.png","nombre":"Quitina gélida","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","nombre":"Voluntad de conquista","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110413.png","nombre":"Quitina gélida","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","nombre":"Voluntad de conquista","cantidad":9}]}]'::jsonb),
  ('hsr-yao-guang', 'honkai-star-rail', 'Yao Guang', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1502.png', '5', 'Físico', null, null, null, 'Júbilo', null, false, null, null, null, null, null, null, false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","nombre":"Crayón de la inocencia","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","nombre":"Crayón de la inocencia","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","nombre":"Pluma creasueños","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","nombre":"Pluma creasueños","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","nombre":"Pincel de los sueños","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110431.png","nombre":"Coágulo invasivo","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","nombre":"Pincel de los sueños","cantidad":9}]}]'::jsonb),
  ('hsr-yukong', 'honkai-star-rail', 'Yukong', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1207.png', '4', 'Imaginario', 80, null, 'Buffer', 'Armonía', 'El pasado y el futuro', false, 'Head of the Sky-Faring Commission on the Xianzhou Luofu. Yukong was a seasoned pilot and a deadshot. Since heading up the commission, she''s been buried under mountains of paperwork.

The Xianzhou Luofu''s Head of the Sky-Faring Commission is gentle, yet seasoned and authoritative. Having been a pilot since young, she had become the commission''s head with her outstanding combat achievements, yet she no longer flies due to a particularly brutal battle. Now, her shine had already dimmed as she shifted her focus to official duties, but she is always seen guiding the course of the Luofu.', 'https://honkai-star-rail.fandom.com/wiki/Yukong%2FLore', 'Head of the Sky-Faring Commission on the Xianzhou Luofu. Yukong was a seasoned pilot and a deadshot. Since heading up the commission, she''s been buried under mountains of paperwork.

The Xianzhou Luofu''s Head of the Sky-Faring Commission is gentle, yet seasoned and authoritative. Having been a pilot since young, she had become the commission''s head with her outstanding combat achievements, yet she no longer flies due to a particularly brutal battle. Now, her shine had already dimmed as she shifted her focus to official duties, but she is always seen guiding the course of the Luofu.', 'https://honkai-star-rail.fandom.com/wiki/Yukong%2FLore', '"¿Sabes una cosa? Solo hay tres tipos de personas que pueden optar a entrar en la Comisión del Transporte Celeste.
Los que tienen el don de la palabra, los que buscan emociones y los que ansían volver a las estrellas. No hay excepciones".

Nosotros somos distintos a los nativos de Xianzhou, con sus vidas interminables. Aunque a los raposianos también se nos considera una raza de larga vida, solo vivimos unos tres siglos. Por eso, a muchos de nosotros nos apasiona más disfrutar de la diversión de la vida y buscamos la máxima intensidad con todo nuestro corazón y nuestra alma.

¿Yo? Ahora mismo tengo 246 años. Estoy con un pie en la tumba y mi tiempo de diversión ha quedado ya muy atrás. Quizá estés al corriente de mis apasionantes costumbres cuando era más joven.', 'https://honkai-star-rail.fandom.com/es/wiki/Yukong', false, '[{"desde":20,"hasta":30,"creditos":3200,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":4}]},{"desde":30,"hasta":40,"creditos":6400,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":8}]},{"desde":40,"hasta":50,"creditos":12800,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110407.png","nombre":"Corona dorada de la sombra del pasado","cantidad":2},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":5}]},{"desde":50,"hasta":60,"creditos":32000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110407.png","nombre":"Corona dorada de la sombra del pasado","cantidad":5},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":8}]},{"desde":60,"hasta":70,"creditos":64000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110407.png","nombre":"Corona dorada de la sombra del pasado","cantidad":15},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":5}]},{"desde":70,"hasta":80,"creditos":128000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110407.png","nombre":"Corona dorada de la sombra del pasado","cantidad":28},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":7}]}]'::jsonb),
  ('hsr-yunli', 'honkai-star-rail', 'Yunli', 'https://enka.network/ui/hsr/SpriteOutput/AvatarRoundIcon/1221.png', '5', 'Físico', 80, null, 'Tanque / DPS', 'Destrucción', 'Danza al atardecer', false, 'A sword hunter from the Xianzhou Zhuming and "the Flaming Heart" General Huaiyan''s darling granddaughter. Frank and straightforward. She has learned swordplay and forging from Huaiyan since young, and thus is the second-youngest prodigy swordmaster of the Flamewheel Octet. Fueled by an intense loathing for the cursed swords that emerged from the Zhuming, she vowed to "hunt down and wipe out all cursed swords."', 'https://honkai-star-rail.fandom.com/wiki/Yunli%2FLore', 'A sword hunter from the Xianzhou Zhuming and "the Flaming Heart" General Huaiyan''s darling granddaughter. Frank and straightforward. She has learned swordplay and forging from Huaiyan since young, and thus is the second-youngest prodigy swordmaster of the Flamewheel Octet. Fueled by an intense loathing for the cursed swords that emerged from the Zhuming, she vowed to "hunt down and wipe out all cursed swords."', 'https://honkai-star-rail.fandom.com/wiki/Yunli%2FLore', 'Ver a su padre refinar espadas en el taller siempre estimulaba su hambre, más de lo normal, probablemente por el intenso calor que emitía la fragua. Como resultado, solía desaparecer entre dos y cuatro horas, durante las que se escabullía al mercado para llenarse la barriga, aparentemente para estar en mejor estado de ánimo para observar y aprender de su padre.

"Esta tienda sirve salchichas de carne más rápido que sus competidores. El chef ensarta las salchichas con maestría, y las atraviesa por el centro con una simetría perfecta. Si aprendiera a blandir espadas, probablemente adoptaría un estilo de lucha enérgico". Eso fue lo que pensó mientras se ponía al final de la fila.

Las bolas de arroz con sésamo de esa tienda normalmente eran preparadas por la propietaria, pero su marido se había encargado hoy de hacerlas. Su antebrazo estaba mucho más tonificado que la parte superior del brazo, posiblemente debido al entrenamiento regular con cuchillas.', 'https://honkai-star-rail.fandom.com/es/wiki/Yunli', false, '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","nombre":"Componente artificial mecánico","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110421.png","nombre":"Permiso de trabajo de la Corporación","cantidad":3},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110421.png","nombre":"Permiso de trabajo de la Corporación","cantidad":7},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","nombre":"Engranaje cilíndrico mecánico","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110421.png","nombre":"Permiso de trabajo de la Corporación","cantidad":20},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":6}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/110421.png","nombre":"Permiso de trabajo de la Corporación","cantidad":35},{"icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","nombre":"Corazón armonioso mecánico","cantidad":9}]}]'::jsonb)
on conflict (id) do update
  set game_id = excluded.game_id,
      name = excluded.name,
      image_url = excluded.image_url,
      rarity = excluded.rarity,
      element = excluded.element,
      level_cap = excluded.level_cap,
      description = excluded.description,
      role = excluded.role,
      path = excluded.path,
      signature = excluded.signature,
      is_upcoming = excluded.is_upcoming,
      biography = excluded.biography,
      biography_source = excluded.biography_source,
      biography_en = excluded.biography_en,
      biography_source_en = excluded.biography_source_en,
      biography_es = excluded.biography_es,
      biography_source_es = excluded.biography_source_es,
      biography_es_translated = excluded.biography_es_translated,
      ascension = excluded.ascension;

-- ---------------------------------------------------------------------------
-- Trazacaminos de Exultacion: en bases antiguas se llamaba "Jubilo" y tenia el
-- id hsr-trazacaminos-jubilo. Se pasa todo lo que apuntaba al viejo (favoritos,
-- tier lists, guias) al id nuevo y se borra el viejo. Si no existe, no hace nada.
-- ---------------------------------------------------------------------------
begin;

insert into public.favorite_characters (user_id, character_id, created_at)
select user_id, 'hsr-trazacaminos-exultacion', created_at
from public.favorite_characters
where character_id = 'hsr-trazacaminos-jubilo'
on conflict do nothing;

insert into public.tier_lists_personal (user_id, game_id, character_id, tier, updated_at)
select user_id, game_id, 'hsr-trazacaminos-exultacion', tier, updated_at
from public.tier_lists_personal
where character_id = 'hsr-trazacaminos-jubilo'
on conflict do nothing;

insert into public.tier_lists_oficial (game_id, mode, character_id, rating, source, updated_at)
select game_id, mode, 'hsr-trazacaminos-exultacion', rating, source, updated_at
from public.tier_lists_oficial
where character_id = 'hsr-trazacaminos-jubilo'
on conflict do nothing;

update public.user_guides
set character_id = 'hsr-trazacaminos-exultacion'
where character_id = 'hsr-trazacaminos-jubilo';

delete from public.characters where id = 'hsr-trazacaminos-jubilo';

commit;

-- Comprobacion
select count(*) as personajes from public.characters where game_id = 'honkai-star-rail';
